/**
 * `core/content/registry.ts` — `contentRef` → `TripContent` resolution.
 * Framework-free: plain TS, no React/Next/`window`. Static-import registry
 * — one pack today; code-splitting a hypothetical second pack is a future concern, not now.
 *
 * `TripContent.legs` is keyed by `TripLeg.contentKey` ('nepal' | 'japan' for the default pack —
 * see `core/trips/packs/nepal-japan-2026.ts`). `LegContent` mirrors EXACTLY what
 * `lib/nepal-data.ts` / `lib/japan-data.ts` already exported before (attractions +
 * food + the category filter list) — this is an indirection layer, not a content redesign.
 *
 * The literal guide data used to live directly in `lib/nepal-data.ts` / `lib/japan-data.ts`;
 * it now lives HERE (byte-identical values) and those two `lib/` files become thin re-export
 * facades over this registry's default-pack entry ( facade pattern, same as
 * `lib/trip-data.ts` over `core/dates`) — same exported names, same values, so every existing
 * consumer (components, hooks, tests) is untouched.
 *
 * Import arrow: this file imports the `Recommendation` TYPE ONLY from `lib/nepal-data.ts`
 * (erased at compile time — no runtime cycle) because `lib/nepal-data.ts` re-exports this
 * file's VALUES. `core/content` still imports nothing from `core/dates` / `core/trips`.
 */
import type { Recommendation } from '@/lib/nepal-data';

// ── Nepal guide content (moved byte-identically from the former lib/nepal-data.ts) ──────────

export const NEPAL_ATTRACTIONS: Recommendation[] = [
  // --- Temples & Cultural Sites ---
  { id: 'na1', image: '/images/nepal/na1.jpg', name: 'Boudhanath Stupa', category: 'Temple', description: 'One of the largest spherical stupas in Nepal, a UNESCO World Heritage Site. The mandala-design dome is surrounded by prayer wheels and monasteries.', bestTime: 'Early morning or sunset', duration: '2-3 hours', photoRating: 5, notes: 'Walk clockwise around the stupa. Best light at golden hour.', location: 'Boudha, Kathmandu', mustSee: true, longDescription: 'Boudhanath is one of the largest stupas in the world and the centre of Tibetan Buddhism in Nepal. The colossal white dome, topped by a gilded tower painted with the all-seeing eyes of the Buddha, was rebuilt after the 2015 earthquake. It sits at the heart of a bustling neighbourhood of monasteries (gompas), thangka workshops and rooftop cafes, and comes alive at dusk when pilgrims circle it clockwise spinning prayer wheels and lighting butter lamps.' },
  { id: 'na2', image: '/images/nepal/na2.jpg', name: 'Swayambhunath (Monkey Temple)', category: 'Temple', description: 'Ancient religious complex atop a hill with panoramic views of Kathmandu Valley. Watch playful monkeys and explore Buddhist and Hindu shrines.', bestTime: 'Sunrise', duration: '2 hours', photoRating: 5, notes: '365 steps to the top. Bring wide-angle lens for cityscape.', location: 'Swayambhu Hill', mustSee: true, longDescription: 'Perched on a hilltop west of the city, Swayambhunath is one of the oldest religious sites in Nepal, its central stupa crowned by the painted eyes of the Buddha gazing in four directions. A steep flight of 365 stone steps lined with prayer flags and resident rhesus macaques (hence "Monkey Temple") climbs to a complex where Buddhist and Hindu shrines mingle. The summit offers one of the best panoramas of the Kathmandu Valley, especially at first light.' },
  { id: 'na3', image: '/images/nepal/na3.jpg', name: 'Pashupatinath Temple', category: 'Temple', description: 'Sacred Hindu temple on the banks of the Bagmati River. Witness cremation ceremonies and the evening aarti ritual.', bestTime: 'Morning or evening aarti', duration: '2-3 hours', photoRating: 4, notes: 'Non-Hindus cannot enter main temple. Cremation photography requires sensitivity.', location: 'Pashupatinath', mustSee: true, longDescription: 'Pashupatinath is Nepal\'s most sacred Hindu temple complex, a sprawling UNESCO-listed site on the banks of the holy Bagmati River dedicated to Lord Shiva. Non-Hindus cannot enter the golden-roofed main temple but can watch openly from the opposite bank, where riverside ghats host public cremations and, each evening, a mesmerising Bagmati aarti of fire, chanting and bells. Sadhus (holy men) in ochre robes and ash gather in the surrounding courtyards.' },
  { id: 'na11', image: '/images/nepal/na11.jpg', name: 'Budhanilkantha Temple', category: 'Temple', description: 'Home to Nepal\'s largest stone statue of the reclining Vishnu, carved from a single block of black basalt and floating in a recessed water tank.', bestTime: 'Early morning', duration: '1-2 hours', photoRating: 4, notes: 'The 5-metre sleeping Vishnu dates to the 7th century. Quiet and uncrowded at dawn.', location: 'Budhanilkantha, north Kathmandu' },
  { id: 'na12', image: '/images/nepal/na12.jpg', name: 'Changu Narayan Temple', category: 'Temple', description: 'The oldest Hindu temple in the Kathmandu Valley and a UNESCO site, famed for exquisite 5th-century stone, wood and metal craftsmanship.', bestTime: 'Morning', duration: '2 hours', photoRating: 5, notes: 'Pair with a short hike down to Bhaktapur or Nagarkot. Newari woodcarving at its finest.', location: 'Changunarayan hill' },
  { id: 'na31', name: 'Vajrayogini Temple, Sankhu', category: 'Temple', description: 'A gilded tantric goddess temple reached by roughly 500 stone steps through pine forest above the medieval town of Sankhu, an hour north-east of Thamel.', bestTime: '09:00-12:00 - the steps are frosty and slick before 09:00 and the north side of the hill stays shaded and cold', duration: '3-4 hours door to door', photoRating: 4, notes: 'Free. 17-20 km north-east, about an hour from Thamel via Boudha and Jorpati, so it stacks ahead of a Boudha, Changu Narayan or Nagarkot run rather than competing with one - it does not cross the city. Photographing the main Vajrayogini image is prohibited and the shrine is often locked; a caretaker will open it for a small offering. Adjacent structures are still being rebuilt, so expect scaffolding. There is a rough vehicle track most of the way up if the 500 steps are not wanted. The Swasthani Brata Katha pilgrimage that swamps Sankhu\'s ghats runs January into February, not December, so you get the empty version.', location: 'Vajrayogini Temple, Bajra Yogini Temple Road, Pukhulachhi, Sankhu, Shankharapur-07, Kathmandu, Nepal', longDescription: 'One of the four Vajrayogini shrines of the Kathmandu Valley and on UNESCO\'s tentative list as Vajrayogini and the early settlement of Sankhu. A stone stairway of roughly 500 steps climbs through pine forest past Licchavi-era stonework and old chaityas half-swallowed by roots to a triple-roofed gilded pagoda with an enormous bronze bell. The main temple survived the 2015 earthquake intact; the town below lost 98 people and about 800 houses, and its rebuilding in traditional brick and timber is itself worth walking. Meditation caves associated with the 84 Mahasiddhas sit just below the temple, reached through the Milarepa Meditation Village gate.', priceHint: 'Free; NPR 2,500-3,500 for a return taxi with waiting' },
  { id: 'na37', name: 'Ram Mandir, Battisputali (Bibaha Panchami)', category: 'Temple', description: 'Kathmandu\'s principal Ram temple, about 1 km from Pashupatinath, and the valley\'s focus for Bibaha Panchami - the re-enacted wedding of Ram and Sita - which falls on Monday 14 December 2026.', bestTime: '16:00-19:00 on 14 December; the temple is open roughly 06:00-19:30 daily', duration: '1-1.5 hours', photoRating: 3, notes: 'Free. Treat it as a 20-minute detour with upside, not a fixed anchor - no source confirms a palanquin procession or Mithila singing groups here, so any set-piece is a bonus. It sits on the Bhaktapur corridor, so come off the highway at Gaushala on the return leg rather than making a separate trip; it is also 1 km from Pashupatinath. There are at least eight \'Ram Mandir\' pins in the valley - confirm by the Ram Darshan Marg street name and ward 9, never by name alone. Modest dress, shoes off inside the shrine, ask before photographing rituals.', location: 'Ram Mandir, Ram Darshan Marg, Sinamangal / Battisputali, Kathmandu-09, Kathmandu 44600, Nepal', longDescription: 'Kathmandu\'s main Ram temple, about 900 m south-west of Pashupatinath, unusual in holding Ram, Sita, Lakshman, Bharat and Shatrughan together, and the place Hindu couples in the city actually marry. Bibaha Panchami, the re-enacted wedding of Ram and Sita on Margashirsha Shukla Panchami, falls on Monday 14 December 2026 and is the only major dated Hindu festival inside this trip; the national centre of it is Janakpur, 6-8 hours away and out of scope. Be clear about what is verified: the date is confirmed across three independent panchang sources and the temple\'s status is documented, but the scale and format of the Kathmandu observance are not documented anywhere - it may be a modest neighbourhood puja. Sinamangal and Battisputali are adjacent, so the temple is popularly called the Battisputali Ram Mandir but is filed under Sinamangal.', priceHint: 'Free' },

  // --- Must-Visit ---
  { id: 'na4', image: '/images/nepal/na4.jpg', name: 'Kathmandu Durbar Square', category: 'Must-Visit', description: 'Historic royal palace square with temples, courtyards, and the living goddess Kumari. A UNESCO site showcasing Newari architecture.', bestTime: 'Morning', duration: '3 hours', photoRating: 5, notes: 'Visit Kumari Ghar to see the living goddess. Entry fee for foreigners.', location: 'Basantapur', mustSee: true, longDescription: 'The old royal square at the heart of Kathmandu (also called Hanuman Dhoka) is a UNESCO World Heritage Site packed with pagoda temples, courtyards and the former royal palace, all in intricate Newari brick-and-timber style. It is home to the Kumari Ghar, residence of the living goddess who occasionally appears at a carved window. Some structures were lost in the 2015 earthquake and restoration continues, but the square remains a living centre of ritual and daily life.' },
  { id: 'na5', image: '/images/nepal/na5.jpg', name: 'Patan Durbar Square', category: 'Must-Visit', description: 'A dense collection of Newari architecture. Krishna Temple, the Golden Temple, and the Patan Museum ring the square.', bestTime: 'Morning to afternoon', duration: '3-4 hours', photoRating: 5, notes: 'The Patan Museum is well worth the time. Explore surrounding alleys for hidden courtyards.', location: 'Lalitpur', mustSee: true, longDescription: 'Across the Bagmati in the city of Lalitpur, Patan Durbar Square is often considered the finest concentration of Newari architecture in the valley. Highlights include the stone Krishna Mandir carved from a single shikhara-style block, the gilded Golden Temple (Hiranya Varna Mahavihar), and the acclaimed Patan Museum housed in a restored palace wing. The surrounding lanes of Patan hide countless Buddhist courtyards (bahals) and metalworking workshops.' },
  { id: 'na6', image: '/images/nepal/na6.jpg', name: 'Bhaktapur Durbar Square', category: 'Must-Visit', description: 'Best preserved medieval city in the Kathmandu Valley. 55-Window Palace, Nyatapola Temple, and traditional pottery squares.', bestTime: 'Full day visit', duration: '5-6 hours', photoRating: 5, notes: 'Try the famous Juju Dhau (King Curd). Least touristy of the three squares.', mustSee: true, longDescription: 'Bhaktapur is the best-preserved medieval town in the Kathmandu Valley, a UNESCO site where car-free brick lanes open onto three linked squares. The Durbar Square holds the 55-Window Palace and the Golden Gate; nearby Taumadhi Square is dominated by the five-tiered Nyatapola, Nepal\'s tallest pagoda, while Pottery Square is still lined with potters spinning clay in the open air. It is famous for its creamy Juju Dhau ("king curd").' },
  { id: 'na32', name: 'Everest Experience Mountain Flight', category: 'Must-Visit', description: 'A 50-60 minute flight along the Himalaya from Kathmandu\'s domestic terminal at around 25,000 ft, with a guaranteed window seat for every passenger - the one thing that beats the December valley haze outright.', bestTime: 'The first departure, 06:15-06:30. Sunrise is 06:44-06:49 mid-December, so the 06:45-07:30 band is the practical sweet spot', duration: '50-60 minutes airborne; about 3-3.5 hours door to door with the 05:00 hotel pickup', photoRating: 5, notes: 'Book direct at buddhaair.com or through the hotel rather than a Thamel street agent; Yeti and Shree fly the same route at similar CAAN-regulated prices. Departs the DOMESTIC terminal, about 600 m north of the international terminal you land at - do not let a driver take you to the wrong one, and do not navigate to a generic KTM pin, which lands mid-airfield. Book it EARLY in the stay: Tribhuvan gets dense winter radiation fog and has been closed outright by it (07:20 to 09:30 on 29 January 2026, visibility down to 500 m). Cancellations are rescheduled or refunded, which is exactly why it must not go on the 18th. Bring a lens cloth - cabin windows smear.', location: 'Domestic Terminal, Tribhuvan International Airport, Ring Road, Sinamangal, Kathmandu 44600, Nepal', mustSee: true, longDescription: 'A flight along the Himalaya on an ATR 72-500 or ATR 42-320, from Langtang Lirung east past Gauri Shankar, Cho Oyu, Everest, Lhotse and Makalu. The aircraft are deliberately loaded well under capacity so every seat is a window seat, and the plane turns so both sides of the cabin get the identical view; crew hand out a peak-identification map and passengers are often invited into the cockpit. Buddha Air rates September to April as the clearest window and mid-December sits comfortably inside it. For a trip staying in the valley with no trek, it is the only way to get level with the big peaks - and the insurance policy for the three ridge mornings the haze can flatten.', priceHint: 'About USD 235 booking direct with Buddha Air; quotes across operators run USD 200-290 for foreign nationals, roughly NPR 18,350-18,650 for Nepali and Indian nationals. Confirm whether taxes and hotel transfer are included.' },

  // --- Hidden Gems ---
  { id: 'na7', image: '/images/nepal/na7.jpg', name: 'Garden of Dreams', category: 'Hidden Gem', description: 'A neo-classical garden oasis in the heart of Kathmandu. Fountains, pergolas, and peaceful pavilions away from city chaos.', bestTime: 'Afternoon', duration: '1-2 hours', photoRating: 4, notes: 'Perfect escape from bustling Thamel. Small entry fee.', location: 'Kaiser Mahal, Kathmandu', longDescription: 'A restored 1920s neo-classical garden built by a Rana general, the Garden of Dreams is a walled Edwardian oasis of pavilions, pergolas, fountains and a lily pond right beside Thamel. Beautifully renovated with Austrian support, it is a favourite spot to escape the noise of the city with a coffee at the Kaiser Cafe. It sits directly next to the Thamel hotel area.' },
  { id: 'na8', image: '/images/nepal/na8.jpg', name: 'Asan Bazaar', category: 'Hidden Gem', description: 'The oldest and most vibrant market in Kathmandu. Spices, vegetables, fabrics, and hidden temples in narrow alleyways.', bestTime: 'Morning', duration: '2 hours', photoRating: 5, notes: 'Best street photography spot in KTM. Follow the ancient trade route.', location: 'Asan, Kathmandu', longDescription: 'Asan is the oldest and busiest bazaar in Kathmandu, a six-way junction on the historic trade route to Tibet. Its dense lanes overflow with vendors selling spices, grains, textiles, brass and fresh produce, and the small Annapurna and Ganesh temples at its centre are still active. Go in the morning for the most energetic scenes — it is widely regarded as the best street-photography spot in the city.' },
  { id: 'na13', image: '/images/nepal/na13.jpg', name: 'Pharping & Asura Cave', category: 'Hidden Gem', description: 'A serene cluster of Buddhist monasteries and the sacred Asura Cave where Guru Rinpoche meditated, set in pine-forested hills south of the valley.', bestTime: 'Morning', duration: 'Half day', photoRating: 4, notes: 'Combine with the Dakshinkali temple nearby. Peaceful and rarely crowded.', location: 'Pharping' },
  { id: 'na24', name: 'Itum Bahal Courtyard', category: 'Hidden Gem', description: 'The largest Newar Buddhist monastery courtyard in old Kathmandu, entered through an unmarked low doorway on the walk between Thamel and Durbar Square - step off a loud bazaar lane and the noise stops.', bestTime: '09:00-11:00, when the sun clears the four-storey walls; also 15:00-16:30', duration: '30-45 minutes', photoRating: 4, notes: 'Free, no ticket, no gatekeeper, no set hours - it is a residential space, not an attraction. People live here: ask before photographing residents, rituals or children, keep out of doorways, and walk clockwise around the chaityas. Do not look for a street number; old-Kathmandu addresses are neighbourhood names, so navigate to the pin or ask for \'Itum Bahal\', which everyone knows. Enclosed on four sides, so before 09:00 it is a cold shadowed box and the pictures fall flat.', location: 'Itum Bahal, off Itumbahal Marg, near Kilagal / Nhaikantala, Kathmandu 44600, Nepal', longDescription: 'Keshchandra Mahavihar is the largest Newar Buddhist monastery courtyard in the old city, still lived in rather than preserved - laundry lines, residents on the plinths, black stone chaityas and carved wooden windows. A row of brass plaques on the wall beside the golden shrine doors depicts Gurumapa, the child-eating demon of local legend. It sits directly on the Thamel-to-Durbar-Square walk and almost nobody on that route goes in. Yetkha Bahal, Takse Baha and Kwathu Baha are within the same few blocks, and the Koti Mahadev temple is immediately beside it.', priceHint: 'Free' },
  { id: 'na25', name: 'Nag Bahal Courtyard, Patan', category: 'Hidden Gem', description: 'A wide open brick courtyard a few minutes north-north-west of Patan Durbar Square with ancient chaityas, a sunken stone hiti and a Rana-era facade, ringed by lived-in Newar houses.', bestTime: '08:00-10:00 or 15:00-16:30, for long low winter light across the brick', duration: '30-45 minutes', photoRating: 4, notes: 'Free, open at any hour, and outside the Patan Durbar Square ticket zone. Living neighbourhood - walk clockwise around the chaityas, ask before close-ups of residents or rituals, keep out of doorways. Some aggregators place it south of Durbar Square; it is north-north-west, about 320 m away, immediately beside the Golden Temple. If you go into the Golden Temple: no leather items at all including belts and bags, shoes off, no photography inside the main shrine.', location: 'Nag Bahal, Lalitpur-16, Lalitpur 44700, Nepal', longDescription: 'A broad brick courtyard about 320 m north-north-west of Patan Durbar Square, holding ancient chaityas, a sunken stone hiti and a Rana-era facade, ringed by lived-in Newar houses. It is the assembly ground for the Samyak Mahadan, the most important Newar Buddhist gathering in Lalitpur, so it is a genuine centre rather than a leftover space. Unlike the tighter Kathmandu bahals it is broad enough to catch long low light right across the paving. It sits beside the Golden Temple, so the two and the Durbar Square chain into one loop.', priceHint: 'Free. The Golden Temple next door is NPR 50 for foreigners and NPR 20 SAARC per the Nepal Tourism Board schedule, not the NPR 100 some blogs quote.' },
  { id: 'na29', name: 'Kirtipur Old Town & Uma Maheshwor Hill', category: 'Hidden Gem', description: 'A fortified Newar hill town 5-8 km south-west of Thamel with a 1,520 m temple knoll at the top giving a 360 over the whole valley - and, on a clear December morning, fog below you and the Langtang snow line above.', bestTime: '08:00-10:00 for the inversion below and the peaks above; 15:30-17:00 for the sunset version', duration: '2-3 hours on site, half a day door to door', photoRating: 4, notes: 'NPR 100 town entry for non-Nepalis when the ticket booth is staffed, which it frequently is not. Taxi from Thamel is 15-30 minutes at about NPR 450-700 (drop at Naya Bazaar), or the local bus from just south of Ratna Park is about NPR 35 and takes 25 minutes. A genuine uphill walk on uneven stone - fine in the cold, less fun after a dawn start. Do Chilancho in daylight: there are repeated local reports of aggressive street dogs there after dark. Newa Lahana, the community-run Newari place, is up here. Kirtipur Municipality\'s own heritage page lists no weapons at Bagh Bhairab, so treat the widely repeated story of captured swords and shields on its walls as unconfirmed.', location: 'Uma Maheshwor Temple, Than-ba-hah Lanh, Kirtipur-03, Kathmandu 44618, Nepal', longDescription: 'A fortified Newar hill town on UNESCO\'s tentative list as the Medieval Settlement of Kirtipur, which resisted Prithvi Narayan Shah\'s siege three times and was punished brutally for it. Uma Maheshwor sits on a 1,520 m knoll at the top of the town and gives a 360 view: the whole Kathmandu Valley on one side and, on a clear December morning, Langtang Himal and Ganesh Himal on the northern horizon. Bagh Bhairab, one of the oldest temples in town and home to Bhairab in tiger form, is on the same peak; the 1515 Chilancho Stupa stands on the other hill about ten minutes away, along with Nagar Mandap Shri Kirti Vihara, the only Thai-style temple in Nepal outside Lumbini. The climb up through the carved-window lanes is half the material.', priceHint: 'NPR 100 town entry when collected, free for Nepalis; NPR 450-700 taxi each way' },
  { id: 'na34', name: 'TU International Cricket Ground, Kirtipur', category: 'Hidden Gem', description: 'Nepal\'s 13,000-seat international cricket ground on the Tribhuvan University campus at Kirtipur, and the loudest public gathering in the valley when Nepal are playing.', bestTime: 'Gates 60-90 minutes before the 10:00 local start; a T20 finishes around 13:15', duration: '3.5-4 hours plus about 45 minutes each way from Thamel', photoRating: 4, notes: 'CHECK THE FIXTURE LIST BEFORE BUILDING A DAY AROUND IT. A three-match T20 series against India A at this ground on 9, 11 and 13 December 2026 was reported but not confirmed as a full playing schedule, and cricket fixtures move - verify with the Cricket Association of Nepal closer to the date. Nepal internationals here have started around NPR 300. Tickets are Khalti-only, so have the hotel buy them if a foreign number will not register. Gates are off the Kirtipur ring road side of the TU campus; no re-entry, limited food inside, bring water. 8-12C at the gates with morning haze over the first hour.', location: 'Tribhuvan University International Cricket Ground, Tribhuvan University premises, Kirtipur, Kathmandu 44618, Nepal', longDescription: 'The national cricket ground on the TU campus at Kirtipur, holding about 13,000, with floodlights installed and inaugurated in November 2025. A full house for a Nepal international is the loudest public gathering in the valley outside a jatra, and the ground sits a 15-minute walk downhill from Kirtipur old town, so a match pairs naturally with that half day. Tickets sell through Khalti, the Cricket Association of Nepal\'s ticketing partner, which generally wants a Nepali mobile number to register.', priceHint: 'Nepal internationals at this ground have started around NPR 300 (about USD 2) with higher stand and VIP tiers; Khalti is CAN\'s official ticketing partner' },
  { id: 'na35', name: 'Taragaon Next', category: 'Hidden Gem', description: 'A contemporary art space inside Carl Pruscha\'s 1970s brick-vaulted modernist hostel complex, about 600 m west of Boudhanath Stupa - architecture that looks like nothing else in Nepal.', bestTime: '10:30-13:00 - the brick vaults and part-open campus are cold before about 11:00 in December', duration: '1.5-2 hours', photoRating: 5, notes: 'Open every day 10:00-17:30 including Saturday, which is unusual in Kathmandu. Tel +977-1-5911857. The recurring Tuesday guided tour and Wednesday crochet circle both require advance registration through a Google Form on taragaonnext.com/whats-on, and no fixed start time is published - register rather than turning up. Check the What\'s On page before going; the slate rotates. No commercial photography without arranging it first. Landmark for a driver: Hyatt Regency, Boudhanath Road, just before Tusal Chowk coming from Chuchhepati. Assume there is nothing on site to eat or drink.', location: 'Taragaon Next, Boudhanath Road, Tusal, Boudha, Kathmandu 44600, Nepal (on the Hyatt Regency premises)', longDescription: 'A contemporary art space inside the restored Taragaon Hostel, Carl Pruscha\'s 1970s complex of semicircular brick vaults and arcades and one of the very few genuinely modernist buildings in Nepal. Rebranded from the old Taragaon Museum, it runs rotating exhibitions, an artist studio and an architecture tracing table, with a sculpture garden and an open-air amphitheatre. Its long-run show \'Metamorphosis: from waste to art\' is listed on its own What\'s On page as running 18 May 2026 to 31 December 2028, so something is guaranteed to be hanging across these dates. It is entirely distinct from Boudhanath Stupa, roughly 600 m east.', priceHint: 'NPR 300 general, NPR 200 students; paid on site by cash or card, no advance booking needed for general entry' },
  { id: 'na36', name: 'Museum of Nepali Art', category: 'Hidden Gem', description: 'Nepal\'s first private art museum, three minutes\' walk from a Thamel base, showing paubha and thangka as art rather than as souvenirs alongside 19th-century-onward Nepali painting.', bestTime: '15:00-17:30 - it fills the dead hour before dinner and the courtyard light is best late', duration: '1-1.5 hours', photoRating: 3, notes: 'Open every day 10:00-18:00 including Saturday. The museum\'s own location page says verbatim \'Entrance from EAST GATE Only\' - do not try the main Kathmandu Guest House lobby. The ticket is valid all day for multiple entries. Ask at reception which galleries allow photography; it varies by exhibition. Carry cash - senior, family and card options are claimed by third parties but are not confirmed on the museum\'s own site. Museum shop open 10:00-20:00. Tel 01-4700800. Pairs naturally with a Garden of Dreams stop about 300 m away.', location: 'Museum of Nepali Art, Kathmandu Guest House courtyard, entrance from the EAST GATE only, Thamel, Kathmandu 44600, Nepal', longDescription: 'Nepal\'s first private art museum, opened in February 2020 by Kathmandu Guest House CEO Rajan Sakya and holding roughly 500 works, about 85% of them from his own collection, by living and historical Nepali artists. It is the one place in the country that shows paubha and thangka as art rather than as merchandise, alongside Nepali painting from the 19th century to the present. Displays rotate rather than being fixed, so what is hanging changes. It is about a three-minute walk from a Thamel hotel by the Garden of Dreams.', priceHint: 'NPR 500 general (about USD 4), 50% off with a valid student ID' },
  { id: 'na38', name: 'Kumbheshwar Technical School', category: 'Hidden Gem', description: 'A WFTO-certified fair-trade workshop a few hundred metres north of Patan Durbar Square where you watch hand-knitting and hand-knotted carpet weaving happen, then buy from the same building.', bestTime: '10:00-15:00, working hours, when the looms are running', duration: '45-60 minutes', photoRating: 3, notes: 'Their own listing gives Sunday-Thursday 09:00-17:00, FRIDAY 09:00-13:00 ONLY, and CLOSED SATURDAY - so Sunday the 13th is the only clean slot in this trip window. Worth re-checking by phone: Nepal moved to a Saturday-Sunday government weekend in April 2026 and their published hours may not have caught up. Tel +977 1 5537484 (older numbers 5437484 / 5439216 do not match their own listing). There is no published visitor policy, so treat the workshop tour as a courtesy and phone ahead if you want to be sure of seeing the looms. Ask permission before photographing weavers. The Jawalakhel Handicraft Centre at the Ekantakuna Tibetan settlement is about 2 km south if you want the Tibetan carpet story too.', location: 'Kumbheshwar Technical School, Bagalamukhi Marg, Chakupat, Lalitpur-11, Lalitpur 44707, Nepal', longDescription: 'Founded in 1983 as a vocational school beside the Kumbeshwar temple and its pond, KTS now provides work to over 2,300 home-based women artisans and funds a free school and an orphanage from its sales. Stock is Tibetan sheep-wool rugs and allo (nettle) and hand-spun silk knitwear, and they will weave a custom rug to your own design. It is the honest version of the pashmina-and-carpet shopping that Thamel does badly, in a quiet corner of old Patan most Durbar Square visitors never turn into.', priceHint: 'Free to visit; knitwear roughly NPR 2,000-6,000. Hand-knotted rugs are a serious purchase and can ship.' },

  // --- Nature ---
  { id: 'na9', image: '/images/nepal/na9.jpg', name: 'Shivapuri National Park', category: 'Nature', description: 'Lush forested national park on the valley\'s northern rim with hiking trails, waterfalls and the Bagmati river source. Rich birdlife and mountain air.', bestTime: 'Morning', duration: 'Half to full day', photoRating: 4, notes: 'Trailhead near Budhanilkantha. Good for a half-day forest hike.', location: 'Shivapuri-Nagarjun' },
  { id: 'na10', image: '/images/nepal/na10.jpg', name: 'Taudaha Lake', category: 'Nature', description: 'A tranquil natural lake on the valley\'s southern edge, a winter stopover for migratory birds and a calm spot for a quiet walk away from the city.', bestTime: 'Late afternoon', duration: '1-2 hours', photoRating: 3, notes: 'Best birdwatching in December. Tea stalls along the shore.', location: 'Chobhar' },

  // --- Photography Locations ---
  { id: 'na14', image: '/images/nepal/na14.jpg', name: 'Chobhar Gorge', category: 'Photography', description: 'A dramatic river gorge where the Bagmati cuts through the valley rim, with the Jal Binayak temple and a vintage suspension bridge framing the water.', bestTime: 'Late afternoon', duration: '1-2 hours', photoRating: 4, notes: 'Wide-angle for the gorge, telephoto for temple detail. Soft side light after 3 PM.', location: 'Chobhar' },
  { id: 'na15', image: '/images/nepal/na15.jpg', name: 'Kopan Monastery Viewpoint', category: 'Photography', description: 'A hilltop Buddhist monastery overlooking Boudhanath and the valley, with prayer flags, golden roofs and sweeping skyline compositions.', bestTime: 'Sunset', duration: '1-2 hours', photoRating: 5, notes: 'Frame Boudhanath stupa against the city below at dusk. Respect monastery quiet hours.', location: 'Kopan hill, Boudha' },
  { id: 'na16', image: '/images/nepal/na16.jpg', name: 'Sarangkot-style Valley Rim at Phulchowki', category: 'Photography', description: 'The valley\'s highest rim peak, blanketed in rhododendron forest, offering layered ridge-line and Himalayan panorama shots on clear winter mornings.', bestTime: 'Pre-dawn to early morning', duration: 'Half day', photoRating: 5, notes: 'Clearest December skies reveal distant peaks. Bring a telephoto for compressed ridges.', location: 'Phulchowki, Godavari' },
  { id: 'na21', name: 'Bhaktapur Pottery Square', category: 'Photography', description: 'A working open-air potters\' quarter five minutes south of Bhaktapur Durbar Square, where black-clay pots dry in rings on the brick and straw-fired kilns smoke at the edges.', bestTime: '07:00-09:00 for potters at the wheel; 11:00-14:00 for the full drying ground', duration: '45-90 minutes', photoRating: 5, notes: 'Open daily 06:00-18:00. Covered by the Bhaktapur city ticket - show your passport at the gate on your first visit and it extends to a week free, which covers both the 14th and the 16th. Stay on the perimeter, do not walk between the drying pots, and ask before close-ups of the potters. Deep shade until about 09:00 on cold mornings. Still photography is fine; filming needs a separate permit from the Department of Archaeology.', location: 'Pottery Square, Talako Tole, Mangalache, Bhaktapur-04, Bhaktapur 44800, Nepal', mustSee: true, longDescription: 'A separate square about five minutes\' walk south of Bhaktapur Durbar Square, reached down the side street by the Kedarnath temple opposite the Golden Gate. The Prajapati potter families work it year round: wheels turn in the open, freshly thrown pots are laid out in rings to sun-dry on the brick, and straw-fired kilns burn at the edges. Mid-December is dry-season peak so the drying ground is at its fullest, where in the monsoon the work moves under shelter. Their busiest making season is the run-up to Tihar in October and November, so expect a working square rather than an overflowing one.', priceHint: 'No separate fee - covered by the Bhaktapur city ticket, NPR 1,800 for foreign nationals, NPR 500 SAARC, free under 10. Listings quoting NPR 1,500 are out of date.' },
  { id: 'na22', name: 'Dharahara Observation Deck', category: 'Photography', description: 'The rebuilt Bhimsen Tower - 22 storeys, two lifts and a 2.5 m wide open-air deck on the 20th floor giving an unobstructed 360 over the old city, with the Himalaya behind it on a clear morning.', bestTime: '08:00-09:30 for the mountain window; about 17:20 sunset for the cityscape', duration: '60-90 minutes including check-in and the lift', photoRating: 4, notes: 'Book a timed slot at dharahara.gov.np/book - date, time and up to four tickets, paid by Khalti or IME Pay, QR code returned, arrive 30 minutes early. Daily entries are capped and slots sell out. Open 08:00-20:00 every day including public holidays; the old Wednesday closure was dropped in July 2025. Lifts have had intermittent faults and the fallback is 213 spiral stairs. As of early 2026 the museum and courtyard were still under construction, so expect the grounds to be a part building site.', location: 'Sundhara Marg, Sundhara, Kathmandu 44600, Nepal', longDescription: 'The rebuilt tower stands 72 m to the roof and 82 m to the pinnacle over 22 storeys, replacing the 1832 Bhimsen Tower that collapsed in the 2015 earthquake. The public viewing deck is on the 20th floor and is 2.5 m wide, reached by two lifts; the 8th-floor circular balcony described in older accounts belonged to the original tower, not this one. It has taken over 600,000 visitors since reopening, which is why daily entry is now capped and slots are booked online.', priceHint: 'NPR 1,000 non-SAARC, NPR 500 SAARC, NPR 200 Nepali; NPR 50 for the grounds only. Ordinary phone and camera use is free - the NPR 1,000/hr photo and NPR 5,000/hr video rates are for commercial shoots.' },
  { id: 'na23', name: 'Rani Pokhari Waterfront', category: 'Photography', description: 'A 17th-century tank in the middle of downtown Kathmandu with a white shikhara temple standing alone in the water, reopened to the public in 2025 and ten minutes\' walk from Thamel.', bestTime: '06:30-08:00 - sunrise is about 06:45 mid-December and the water is dead still', duration: '20-30 minutes', photoRating: 4, notes: 'Open daily 05:00-16:00 and free, so there is no sunset shot here. Reopened to the public in March 2025 - guidebooks and blogs saying it is shut 364 days a year are out of date. The temple in the middle of the pond opens only on Bhai Tika in mid-November, so on these dates you shoot it across the water. About a 10-15 minute walk south-east from Thamel via Jamal, or 5 minutes by taxi. Managed by Kathmandu Metropolitan City\'s Shankhadhar Garden and Ranipokhari Unit.', location: 'Rani Pokhari, Jamal, Kathmandu 44600, Nepal', longDescription: 'A 180 x 140 m tank built in the 17th century by King Pratap Malla, with the white Balgopaleshwor shikhara temple standing alone in the middle of the water. Kathmandu Metropolitan City opened the restored waterfront to the public, daily and free, on 24 March 2025. The 2016-2020 restoration was politically contested and what stands is the 1670 form rebuilt in brick and clay, not the concrete-and-cafe scheme originally proposed. A stone elephant carrying Pratap Malla stands on the south side.', priceHint: 'Free' },

  // --- Day Trips ---
  { id: 'na17', image: '/images/nepal/na17.jpg', name: 'Nagarkot Sunrise', category: 'Day Trip', description: 'Famous hilltop viewpoint offering panoramic sunrise views over the Himalayan range including Everest, Langtang and Ganesh Himal.', bestTime: 'Pre-dawn to sunrise', duration: 'Half day', photoRating: 5, notes: 'Leave Kathmandu by 4:30 AM. Bring tripod and telephoto lens.', location: 'Nagarkot', mustSee: true, longDescription: 'Nagarkot is a ridge-top village about 30 km east of Kathmandu, famed for its sweeping Himalayan horizon. On clear winter mornings the sunrise reveals a long arc of peaks — including the Langtang, Ganesh Himal and Rolwaling ranges, and on the clearest days a distant glimpse of Everest. December offers some of the year\'s best visibility. Stay overnight or leave the city very early to catch first light from a viewpoint tower.' },
  { id: 'na18', image: '/images/nepal/na18.jpg', name: 'Chandragiri Hills Cable Car', category: 'Day Trip', description: 'Cable car ride to a hilltop with stunning views of the Himalayas and Kathmandu Valley. Clear winter days offer Everest views.', bestTime: 'Clear morning', duration: '3-4 hours', photoRating: 5, notes: 'December offers clearest mountain views. Bring layers for cold at the top.', location: 'Chandragiri' },
  { id: 'na19', image: '/images/nepal/na19.jpg', name: 'Dhulikhel', category: 'Day Trip', description: 'A historic Newari town on the valley\'s eastern edge with cobbled streets, traditional architecture and a renowned wraparound Himalayan panorama.', bestTime: 'Sunrise or sunset', duration: 'Full day', photoRating: 5, notes: 'About 30 km from Kathmandu. Walk the ridge to the Kali shrine viewpoint.', location: 'Dhulikhel, Kavre' },
  { id: 'na20', image: '/images/nepal/na20.jpg', name: 'Namo Buddha', category: 'Day Trip', description: 'One of Tibetan Buddhism\'s holiest sites, home to the Thrangu Tashi Yangtse Monastery set among terraced hills and forest stupas.', bestTime: 'Morning', duration: 'Full day', photoRating: 4, notes: 'Pair with Dhulikhel and Panauti for a scenic loop. Vegetarian meals at the monastery.', location: 'Namobuddha, Kavre' },
  { id: 'na26', name: 'Kailashnath Mahadev Statue, Sanga', category: 'Day Trip', description: 'A 44 m standing Shiva in copper, zinc, steel and concrete on a bare hilltop at the pass where the Kathmandu Valley ends, 15 minutes east of Bhaktapur on the Araniko Highway.', bestTime: '07:30-09:30 for empty terraces, raking light on the copper and the clearest Himalayan horizon', duration: '45-75 minutes on site; 15 minutes from Bhaktapur, about an hour from Thamel', photoRating: 5, notes: 'Grounds open 07:30-18:00; you can walk up earlier for sunrise if you park outside the main lot. Two entrances at different prices - the motorable road delivers you to the Hilltake resort gate at NPR 100 for parking and access, while the separate footpath gate to the left is nominally free but staff often ask NPR 25. Sanga is about 8 km PAST Bhaktapur heading away from Kathmandu, so it is a 30-45 minute round-trip backtrack, not the free add-on it looks like on a map. Busy on both weekend days now that Nepal runs a Saturday-Sunday weekend, so go on a weekday morning. Exposed and genuinely cold and windy before 09:00. Onsite canteens are overpriced; the one near the free gate is about half.', location: 'Kailashnath Mahadev Statue, Araniko Highway, Palase, Suryabinayak-10, Suryabinayak Municipality, Bhaktapur 44800, Nepal', longDescription: 'A 44 m (143 ft) standing Shiva built between 2003 and 2010 in copper, zinc, steel and concrete, on a hilltop at the pass where the Kathmandu Valley ends. It is the tallest Shiva statue in Nepal, but it has NOT been the world\'s tallest since 2022, when the 112 m Vishwas Swaroopam was unveiled at Nathdwara in Rajasthan - most Nepali guides, tour listings and product pages still say otherwise. A 738 ft pedestrian suspension bridge crosses the Araniko Highway to reach it and is a frame in its own right. On a clear December morning the statue silhouettes against the eastern Himalaya.', priceHint: 'NPR 0-100 depending on which gate. Taxi about NPR 800 from Bhaktapur or NPR 2,000 from Kathmandu, but treat those as a floor - petrol has run near NPR 172/litre through 2026 and operators are adding fuel surcharges.' },
  { id: 'na27', name: 'Bungamati Woodcarvers\' Village', category: 'Day Trip', description: 'A Newar woodcarving town 10 km south of Patan whose 16th-century shikhara temple, flattened in 2015, was rebuilt and reconsecrated in 2025 - carvers still work in open street-front shops around the square.', bestTime: '10:00-13:00, when the carving workshops are open and the sun is on the brick', duration: '1.5-2 hours; 3-4 hours combined with Khokana', photoRating: 4, notes: 'Free. About 40-50 minutes from Thamel by taxi; walkable to Khokana in 20-25 minutes over the Karya Binayak ridge, which is itself a valley viewpoint. Avoid Saturday - it is Nepal\'s weekly holiday and many workshops shut; Sunday and Thursday are working days. Be honest about the rebuild: much of the surrounding housing came back as painted concrete rather than tiled brick, and a guide updated in January 2026 still describes renovation as incomplete, so expect some scaffolding in frame. There is an army camp on the village edge tied to the Kathmandu-Terai Fast Track land dispute - be discreet with the camera near it.', location: 'Rato Machhindranath Temple, Machhindra Nath Marga, Bungamati, Lalitpur-22, Lalitpur 44700, Nepal', mustSee: true, longDescription: 'A Newar woodcarving town on a spur above the Bagmati where roughly 700 buildings came down in 2015, the 16th-century shikhara temple among them. The rebuilt white four-pinnacled shikhara was topped out on 22 May 2025 and the Rato Machhindranath idol was reinstalled in its original spot on 1 June 2025, ten years after it was displaced. The deity runs a six-month cycle between here and Ta:Baha in Patan and is carried to Patan a few days before Yomari Punhi, which falls on 24 December 2026 - so it is in residence at Bungamati for this entire trip. Much of the carved window and strut work sold in Patan is actually cut here.', priceHint: 'Free; about NPR 2,500-3,500 for a half-day taxi covering Bungamati and Khokana with waiting' },
  { id: 'na28', name: 'Khokana and the Mustard-Oil Mills', category: 'Day Trip', description: 'A UNESCO tentative-list village 20 minutes\' walk from Bungamati, with its medieval street plan intact and a mustard-oil industry still worked on a wooden beam press.', bestTime: '11:00-14:00 - the mills run through the working day and the interiors are very dark', duration: '1-1.5 hours; 20-25 minutes\' walk from Bungamati', photoRating: 4, notes: 'Free. Ask specifically for the traditional wooden press rather than assuming any open door has one - most mills here are motorised now, and sources disagree on who runs which, so navigate to the village and ask locally. Small bottles of cold-pressed oil sell for a few hundred rupees and are the genuinely local souvenir. Mill floors are hot, dark and crowded with no guardrails; watch your feet and ask before photographing workers. Closed-feeling on Saturday, Nepal\'s weekly holiday. Mid-December is likely before the yellow mustard bloom, which peaks January to mid-February at this altitude - expect green fields.', location: 'Sri Rudrayani Temple, Thalachi Marga, Khokana, Lalitpur-21, Lalitpur 44700, Nepal', longDescription: 'Khokana has been on UNESCO\'s tentative list since 1996 not for a single monument but for the whole village - a medieval settlement with its original drainage and chowks. Of the four Malla-era wooden lever presses, one is still worked: Gabu Jya Sa, kept running by Kanchha Maharjan on a hearth roughly 300 years old, where seed is sifted in a bamboo tray, slow-roasted over an open fire and pressed between two enormous horizontal beams. The village has 10-15 oil mills in total but the rest have gone over to modern machinery. The single straight main street of three-storey brick facades runs down to the three-tiered Rudrayani temple.', priceHint: 'Free' },
  { id: 'na30', name: 'Panauti', category: 'Day Trip', description: 'A medieval Newar town beyond Banepa holding one of Nepal\'s oldest surviving pagoda temples, with a street plan on UNESCO\'s tentative list and almost no other foreigners in the frame.', bestTime: 'Arrive 09:30-10:30 once the side-valley fog burns off; woodwork and the ghats shoot best 15:00-16:30', duration: '2.5-3 hours on site, 6-7 hours door to door from Thamel', photoRating: 5, notes: 'NPR 300 combined ticket covers the Indreshwar complex and the volunteer-run Panauti Museum 40 m away in the same courtyard. No published opening hours could be confirmed anywhere - the complex is open through the day, but do not plan around a closing time. About 32 km via the Araniko Highway to Banepa then south, sealed the whole way, 1h15-1h45 by private car depending on Koteshwor traffic; the Ratna Park bus runs every 15 minutes for NPR 60 and takes about 1h35. Carry cash - there is no ATM you should rely on. Worth adding the 20-minute concrete-stair climb to the hilltop viewpoint above town, which is not the Brahmayani temple down at river level.', location: 'Indreshwar Mahadev Temple, NH15, Sunthan, Panauti-09, Kavrepalanchok 45209, Nepal', mustSee: true, longDescription: 'One of Nepal\'s oldest towns and, on UNESCO\'s tentative list, the best-preserved medieval Newar street plan outside the three Durbar Squares. The Indreshwar Mahadev, dated to 1294 CE, is among the oldest surviving pagoda temples in the country, came through 2015 in good condition, and carries erotic and mythological roof struts from the 13th century. The town sits at Tribeni Ghat, where the Roshi and Punyamata rivers meet below the 1715 three-roofed Brahmayani temple. One caveat its reputation hides: Panauti Durbar Square itself is in early-stage reconstruction with French Embassy funding and is currently a building site - the temples are repaired and fine.', priceHint: 'NPR 300 entry; NPR 5,000-8,000 for a private car for the day, or NPR 60 each way by bus' },
  { id: 'na33', name: 'Chitlang, over the Chandragiri Ridge', category: 'Day Trip', description: 'A Licchavi-era Newar village on the far side of the Chandragiri ridge in Makwanpur, reached by riding the cable car up and walking two hours downhill into a completely different valley.', bestTime: 'Cable car up 09:00-10:00, walk down 11:00-13:00, cheese and lunch in the village, road pickup about 15:00', duration: 'Full day, about 8 hours', photoRating: 4, notes: 'This lives or dies on the driver knowing the pickup point - agree it before leaving Thamel; the return via the Kulekhani road is about 2 hours. Cable car hours are 08:00-17:00 weekdays and 07:00-18:00 weekends, shorter than some listings claim. The trailhead at the top station is an unsigned path next to the men\'s bathroom between the yellow snack shops: descend the stairs to a road, turn left at the police checkpoint, and ask further down for the steep trail into the woods. The goat-cheese farm is a family homestay, not a shop with fixed hours - call ahead or you may arrive to a closed door. December has no mud and no leeches, which is why nobody walks this June to September. Navigate to a named target such as Chitlang Organic Village Resort; the pin marks a village strung along about a kilometre of valley, not a building.', location: 'Chitlang, Thaha-09, Thaha Municipality, Makwanpur 44619, Nepal', longDescription: 'A Licchavi-era Newar village on the old Kathmandu-to-India trade road, over the Chandragiri ridge and outside the Kathmandu Valley in Makwanpur district. Riding the cable car up and walking down turns a 90-minute round trip into a real day out: the moment the trail crests the ridge, Kathmandu disappears behind you and an empty green valley opens ahead. Satdhara, a set of seven old stone spouts, is in the village, along with Nepal\'s first goat-cheese farm - run by Ashok Singh Thakuri, who trained in France and Belgium - which does tours, tastings and plum wine. The cable car was torched on 9 September 2025 during the Gen Z protests and shut for nearly two months; it resumed service on 8 November 2025 and runs at normal pricing.', priceHint: 'Cable car USD 13 one way, about USD 22 return for foreigners, plus NPR 6,000-8,000 for a car with the Chitlang pickup' },
];

export const NEPAL_FOOD: Recommendation[] = [
  { id: 'nf1', image: '/images/nepal/nf1.jpeg', name: 'Bhojan Griha', category: 'Food', description: 'Traditional Nepali feast in a 150-year-old heritage building with cultural performances. Multi-course dal bhat dinner.', bestTime: 'Dinner', duration: '2 hours', photoRating: 4, notes: 'Reservation recommended. Cultural dance show included.', location: 'Dillibazar, Kathmandu', longDescription: 'Set in a lovingly restored 19th-century Rana-era mansion in Dillibazar, Bhojan Griha serves a multi-course traditional Nepali feast (a fixed set menu of dal bhat, curries, pickles and sweets) accompanied by live folk music and dance performances. It is a popular, atmospheric introduction to Newari and hill-Nepali cuisine — reservations are recommended, especially in the evening.' },
  { id: 'nf2', image: '/images/nepal/nf2.jpg', name: 'Yangling Restaurant', category: 'Food', description: 'Legendary momo spot in Thamel. Steamed, fried, and jhol momos with authentic Tibetan-Nepali flavors.', bestTime: 'Lunch', duration: '1 hour', photoRating: 3, notes: 'Try the jhol (soup) momos. Simple atmosphere, incredible food.' },
  { id: 'nf3', image: '/images/nepal/nf3.jpg', name: 'OR2K Restaurant', category: 'Café', description: 'Mediterranean-Nepali fusion with stunning rooftop views. Cushion seating, hookah-friendly, great hummus and falafel.', bestTime: 'Breakfast or sunset', duration: '1.5 hours', photoRating: 4, notes: 'Rooftop sunset views are magical. Vegetarian-friendly.' },
  { id: 'nf4', image: '/images/nepal/nf4.jpg', name: 'Cafe Swotha', category: 'Food', description: 'Newari cuisine served in a beautifully restored heritage courtyard in Patan. Authentic local flavors in elegant setting.', bestTime: 'Lunch', duration: '1.5 hours', photoRating: 4, notes: 'Try the Newari set meal. Beautiful courtyard architecture.' },
  { id: 'nf5', image: '/images/nepal/nf5.jpg', name: 'Roadhouse Cafe', category: 'Café', description: 'Best wood-fired pizza in Kathmandu with craft beer selection. Modern atmosphere, popular with expats.', bestTime: 'Dinner', duration: '1.5 hours', photoRating: 3, notes: 'Multiple locations. Thamel branch has best atmosphere.' },
  { id: 'nf6', image: '/images/nepal/nf6.jpeg', name: 'Thakali Kitchen', category: 'Food', description: 'Authentic Thakali dal bhat - the quintessential Nepali meal. Unlimited refills on rice, dal, vegetables.', bestTime: 'Lunch', duration: '1 hour', photoRating: 3, notes: 'Eat with right hand for authentic experience. Dal bhat power!' },
  { id: 'nf7', image: '/images/nepal/nf7.jpg', name: 'Himalayan Java', category: 'Café', description: 'Nepal\'s premier coffee chain using locally grown beans from the hills. Multiple scenic locations across Kathmandu.', bestTime: 'Morning', duration: '1 hour', photoRating: 3, notes: 'Try Nepali-grown coffee. Garden-view branch near Thamel is best.' },
  { id: 'nf8', name: 'Newa Lahana', category: 'Food', description: 'A community-run Newari khaja ghar on the Kirtipur hilltop where the kitchen is a Newar co-operative, rice beer is brewed on site and the top floor looks across to the Chandragiri ridge.', bestTime: 'Lunch, 12:00-14:30 - the top floor is unheated and the Chandragiri view is a daylight thing', duration: '1.5-2 hours', photoRating: 4, notes: 'Open daily - their own contact page lists Mon-Fri 10:30-21:00 and Sat-Sun 10:00-21:00. No reservation needed. Cash is safest. After about 16:00 ask for an indoor floor; the rooftop gets cold fast once the sun drops, and the ridge hazes over after 15:00. Phones 986-0742022 / 984-9029966 / 984-1330533. A claimed Bhaktapur branch could not be verified and Foodmandu\'s listing says there are no other branches, so treat the Kirtipur house as the only one.', location: 'Newa Lahana, Thambahal-1, Kirtipur 44618, Nepal (walk past Bagh Bhairab temple and look for the gate with the signboard)', longDescription: 'A multi-storey open-air khaja ghar run as a Newar co-operative rather than by a chef, which is why Kathmandu\'s own food writers treat it as the Newari benchmark. Thwo, the local rice beer, is brewed on site and served in clay salicha cups. Order the full khaja set plus choila, mixed wo and bara, and sukuti; pangra and tishyo are the adventurous end. The top-floor terrace looks straight across Machhegaun to Chandragiri.', priceHint: 'NPR 500-1,000 per person; individual plates NPR 35-180' },
  { id: 'nf9', name: 'Honacha', category: 'Food', description: 'A smoke-blackened Newari eatery that has been frying black-lentil bara on the same tawa behind Patan\'s Krishna Mandir for 60-70 years, under the same family.', bestTime: '11:00-14:00 - they cook a set quantity and stop when it goes', duration: '30-45 minutes', photoRating: 4, notes: 'PIN CAVEAT: the same family runs TWO Honachas less than 20 m apart - the original behind Krishna Mandir (this one) and a sister shop next to the Bhimsen Temple on the northern edge of the square. No map pin separates them, so expect to ask. Cash only, phone 015451255. Sells out and shuts early on busy days and their own Facebook has posted same-day closures, so have a fallback in the square. Basic hygiene caveat is real: stick to what comes off the tawa hot. Low light, so shoot wide open and ask before pointing a lens at staff. No heating - in December you eat in your jacket.', location: 'Honacha, Shahid Shukra Raj Sadak Paschim, Mangal Bazar, Patan Durbar Square, Lalitpur-16, Lalitpur 44700, Nepal (the alley immediately behind and west of Krishna Mandir)', longDescription: 'Run by the Byanjankar family for 60-70 years on the same spot about 100 m from Patan Durbar Square, with no real seating - you eat standing or on stools in a low, sooty, unglazed room. Almost everything is buffalo: chwela, kachila, bhuttan, sukuti, sapu mhicha and organ meats, so vegetarians are limited to plain bara and the spicy potato gravy. Come for the room and the history as much as the cooking - a Nepali Times review notes that some Kathmandu eaters rate other Newari kitchens above it.', priceHint: 'NPR 150-400 per person; the Kathmandu Post logged NPR 80-200 per item' },
  { id: 'nf10', name: 'Aama ko Bara Pasal', category: 'Food', description: 'A two-metre-wide shopfront beside Nyatapola where Bikumaya Bajracharya has made bara since the early 1970s, turning over around 300 people a day.', bestTime: '10:00-14:00 - they cook a fixed quantity and it goes', duration: '20-30 minutes', photoRating: 4, notes: 'PIN CAVEAT: OpenStreetMap has no node for this shop. The pin sits between the Nyatapola temple node and Taumadhi Square, so it should be within 30-60 m - everyone in Taumadhi knows the shop by name, so ask rather than trusting the dot. Cash only, no reservations, no English menu, tiny and unheated. She would be about 80 in December 2026 and runs it with her daughter-in-law, so do not bank on a portrait of Aama herself; ask before photographing anyone. Reaching it needs the Bhaktapur heritage ticket at NPR 1,800 for foreigners - some 2026 listings still quote NPR 1,500.', location: 'Aama ko Bara Pasal, 12 Rammandir Road, Taumadhi Square, beside Nyatapola Temple, Bhaktapur 44800, Nepal', longDescription: 'Bikumaya Bajracharya - known to everyone simply as Aama - has fried bara on this spot since the early 1970s. There is no menu: veg, egg, buff or mixed bara, cooked in front of you, with aalu on the side. Ask for the jhol, the broth poured over the top, which regulars treat as the whole point. She stopped selling samaybaji and choila years ago, so it is bara and cold drinks now. It is the single most local thing you can eat in Bhaktapur.', priceHint: 'Under NPR 300 per person - an April 2026 review logged egg bara NPR 100, mixed NPR 125, aalu NPR 50' },
  { id: 'nf11', name: 'Tukche Thakali Kitchen', category: 'Food', description: 'Family-run since 1997 and named for Tukche village in the Kali Gandaki, with spicing closer to a real Thakali set than the milder chain versions - and a distinct business from the Thamel \'Thakali Kitchen\'.', bestTime: 'Lunch 12:00-14:30, or dinner from 18:30; the kitchen closes 21:00', duration: '1-1.5 hours', photoRating: 3, notes: 'Open daily 10:30-21:00 (one listing says 11:00). A 10-minute taxi from Thamel. Reservations not usually needed; phones 01-4530356 / 01-4512462 / 9851053044. Two branches only - this Gairidhara one and Jhamsikhel, opened 1 January 2024. OpenStreetMap also carries a stale node for the closed Uttar Dhoka premises; do not follow that one. Dhedo and the hot black-lentil dal are the right order on a cold valley evening. There is a small courtyard as well as the main room.', location: 'Tukche Thakali Kitchen, Gairidhara Road, Bhrikuti Tol, opposite SK Bhawan, Gairidhara / Tangal, Kathmandu-02, Kathmandu 44600, Nepal', longDescription: 'Family-run since 1997 and named for Tukche village in the Kali Gandaki, with many ingredients sourced from the Thak Khola region. The dhedo - buckwheat dough - and the thick black-lentil dal are the things to order, and the spicing is noticeably closer to a real Thakali set than the milder chain versions. The room is built as a Thakali interior rather than a generic thali hall, in warm wood and brass. This is NOT the \'Thakali Kitchen\' already on the app\'s list, which is a separate Thamel restaurant near Z Street.', priceHint: 'Thakali khana set roughly NPR 500-900; larger listings put average spend nearer NPR 2,000 with extras' },
  { id: 'nf12', name: 'Chez Caroline', category: 'Food', description: 'French bistro cooking in the courtyard of Baber Mahal Revisited since 1997 - a restored Rana palace and stable complex with whitewashed arcades and no traffic noise.', bestTime: 'Lunch 12:00-14:30 for courtyard sun, or dinner from 18:30; the kitchen closes 21:00', duration: '1.5-2 hours', photoRating: 4, notes: 'Open 08:00-21:00 every day including Saturday - ignore any listing that says closed Mondays, which is years out of date. Courtyard tables get cold after sunset (about 17:15 mid-December), so take the courtyard at lunch and ask for indoors at night. Reservations recommended for dinner: 01-5363070 / 01-5364187, chezcarolinenepal@gmail.com. Older pages list 01-4263070 / 01-4254268 - those are pre-renumbering and may not connect. Ask about seasonal specials rather than ordering off the standing menu. Build in 30-40 minutes to walk the complex.', location: 'Chez Caroline, Baber Mahal Revisited, Tanka Prasad Ghumti Sadak, Singha Durbar, Kathmandu-11, Kathmandu 44617, Nepal', longDescription: 'Genuine French bistro cooking under Chef Gopal, holding the courtyard of Baber Mahal Revisited since 1997. The complex is a restored Rana palace and stable block and is arguably the best surviving museum of Rana architecture in the city - whitewashed arcades, wrought iron, tables under the colonnade. It also holds galleries and craft shops, including the Siddhartha Art Gallery, Nepal\'s most serious contemporary gallery, founded in 1987 and open Sun-Fri 11:00-17:00 and Saturday 12:00-17:00 with free entry. It is the one place on this list where the setting and the kitchen are both worth the trip.', priceHint: 'NPR 2,000-4,000 per person with wine, NPR 1,200-2,000 without; their published menu runs starters NPR 495-1,650 and desserts NPR 530-550, tax included' },
  { id: 'nf13', name: 'Raithaane', category: 'Food', description: 'Modern Nepali as preservation rather than fusion - eastern-Nepal pork, Sherpa stews, western batuk with chukauni - built on heritage grains sourced direct from farmers, with a seasonally rotating menu.', bestTime: 'Lunch from 12:30, or an early dinner - the kitchen closes around 20:30, so dinner means a 19:00 sitting', duration: '1.5 hours', photoRating: 4, notes: 'CLOSED MONDAYS - Dec 14 is out. Open Tue-Sun 12:30-20:30; a listing showing 06:45-14:45 is printing UTC and means the same hours. It has MOVED from its original Saugal courtyard: OpenStreetMap and Atlas Obscura still carry the old Hakha Tol address, which is wrong. This pin is the Kupondole Heights block rather than a specific door, so allow a minute to find it. Reservations accepted on +977 9801002971. They also run Sunday cooking classes. There is terrace seating for daylight.', location: 'Raithaane, Kupondole Heights Road, Kupondole Ward 1, Lalitpur 44600, Nepal', longDescription: 'A kitchen built around heritage grains and near-extinct produce bought direct from farmers: eastern-Nepal pork dishes, Sherpa stews, western batuk with chukauni, Terai fritters, foxtail-millet salad and a juju dhau pie, with house pickles made in-house. The menu rotates seasonally, so a December visit gets the winter version. Prices are deliberately kept low enough that young Nepalis eat here, which is the point of the place.', priceHint: 'Around NPR 1,000 per person average spend' },
  { id: 'nf14', name: 'Restaurant TUSA', category: 'Food', description: 'A twelve-seat tasting-menu room in a rebuilt Newari courtyard house in Bhaktapur, run by a chef who interned at Noma - seven courses of indigenous Nepali ingredients.', bestTime: 'Dinner - a single strict seating window of 17:30-19:30. Lunch is also served, same seven-course format', duration: 'About 1.5 hours for the seven courses, plus travel', photoRating: 5, notes: 'BOOK WEEKS AHEAD - twelve covers, and a travel writer was turned away for a weekend request. Reserve on +977 9821055559 / +977 9705777999, tusadining23@gmail.com, or the form at tusanepal.com; confirm operating days and that they are trading in December 2026, since they have taken multi-day research breaks before. Allow 60-90 minutes from Thamel - one writer\'s 45-minute estimate became 90, and their own site warns about punctuality. If you take it as a last-night splurge on the 18th, the 17:30 seating ends about 19:00 and Bhaktapur is 30-40 minutes from the airport side of the city, but you will have checked out of Thamel, so settle where the luggage goes first. No smoking, no pets. Bhaktapur heritage-zone entry may apply depending on the gate. They also run a \'Tusa Canberra\' in Australia - this is the Bhaktapur house.', location: 'Restaurant TUSA, Nagpokhari, Bhaktapur 44800, Nepal (just off the Bhaktapur pokhari, east of Durbar Square; Plus Code MCFM+G9J)', mustSee: true, longDescription: 'Chef Parashuram Pathak interned at Noma in Copenhagen and cooked abroad before opening TUSA on Nepali New Year 2024, in a rebuilt Newari courtyard house with about twelve seats in azure Solukhumbu fabric. The format is seven courses of indigenous Nepali ingredients - fermented potato and millet roti with charred green garlic, charred fish in broth, sisnu nettle sponge, juju dhau cheesecake. It is the most ambitious kitchen in the valley right now and nothing else on this list is remotely like it.', priceHint: 'NPR 7,500 per person including VAT for the seven-course tasting menu, before drinks; a 50% advance payment is required to hold the booking' },
  { id: 'nf15', name: 'Le Sherpa & the Saturday Farmers\' Market', category: 'Food', description: 'The valley\'s farm-to-table standard-bearer, whose lawn becomes a 40-vendor farmers\' market every Saturday morning - and Saturday 12 December is the only Saturday of this trip.', bestTime: 'Market Saturday 08:00-12:30; arrive 08:30-09:30, bread and pastries sell out well before the close. Restaurant brunch 08:00-13:00 Sat and Sun', duration: '1.5-2 hours for the market, 2-3 hours with brunch', photoRating: 4, notes: 'MARKET IS SATURDAY-ONLY, 08:00-12:30 per Le Sherpa\'s own page - an old Tripadvisor review claiming a Wednesday edition is wrong. Restaurant hours differ by day: 11:00-22:00 Mon-Fri, brunch 08:00-13:00 Sat and Sun, with prior reservation required for breakfast. About 3.2 km from Thamel, so 40-45 minutes on foot or a 15-20 minute taxi at NPR 300-400. Reservations +977 9801159480 / 01-4528604, dine@lesherpa.com.np. Cash is easiest; some vendors take Fonepay or eSewa QR only. Bring a bag and small notes. Note it clashes with the Boudha Farmers Market at Utpala Cafe, same morning, 4 km away - pick one.', location: 'Le Sherpa, Ramalaya Complex, Devkota Galli, Maharajgunj / Panipokhari, Kathmandu-03, Kathmandu 44616, Nepal (opposite Sheetal Niwas, the President\'s House)', longDescription: 'Two things at one address. The restaurant works from its own herb and vegetable gardens and dozens of small producers, on a short changing modern-European menu. On Saturday mornings the lawn becomes the Farmers\' Market, running since 2010 with around 40 vendors: Himalayan French cheese, yak blue cheese, artisan bread, honey, fresh fish, juju dhau, Mustang apples and citrus, plus hot food stalls. December is its best month, and it is the best single place in the city to see where the good ingredients actually come from.', priceHint: 'Market entry free, stall items NPR 200-1,500; restaurant brunch roughly NPR 1,200-2,500 per person' },
  { id: 'nf16', name: 'kar.ma Coffee', category: 'Café', description: 'Nepal\'s benchmark third-wave roaster, buying single-origin lots direct from mid-hill farmer families, with a full hand-brew bar hidden on Level 2 of the Gyan Mandala building in Jhamsikhel.', bestTime: '07:00-09:30 - it opens at 07:00, early for Kathmandu, and the upstairs room is brightest and emptiest before 09:30', duration: '45-75 minutes', photoRating: 4, notes: 'Open 07:00-20:00 daily, confirmed on the roaster\'s own visit page for both outlets. It is on Level 2 and invisible from street level - look for the stairs. Beans sold to take home, cards accepted. About 10 minutes on foot or 5 by taxi from Patan Durbar Square. Their second outlet on Pawo Gompa Road in Boudha is literally next door to Utpala Cafe, so do not schedule both on the Boudha morning - pick one.', location: 'kar.ma Coffee, Gyan Mandala building, Level 2, Jhamsikhel, Lalitpur (Patan) 44700, Nepal', longDescription: 'Austrian-founded and the one specialty name the Kathmandu coffee trade agrees on. It buys single-origin lots direct from mid-hill farmer families and runs a full hand-brew bar - V60, moka pot, AeroPress, French press - alongside single-origin espresso, in an earthy room with hanging greenery. Beans are sold to take home.', priceHint: 'NPR 200-450 per drink; 250 g of beans about NPR 900-1,200' },
  { id: 'nf17', name: 'Utpala Cafe', category: 'Café', description: 'A monastery-run vegetarian cafe with the best sunny walled garden in Boudha, three minutes off the kora - and on Saturdays the garden hosts the Boudha Farmers Market.', bestTime: '07:00-09:30 any day. On Saturday get there by 08:00, before the garden fills', duration: '60-90 minutes', photoRating: 4, notes: 'Open 07:00-21:00 daily. On Saturdays the Boudha Farmers Market runs in this garden roughly 08:00-14:00, the kitchen switches to a buffet 08:00-15:00 rather than a-la-carte, and the garden is packed from about 09:30 - a plus if you want the market, a minus if you want quiet, and worth confirming it is running that week. Saturday 12 December is the trip\'s only Saturday, and it collides with Le Sherpa\'s market across town. Free wifi and ample power, free parking, no alcohol, no smoking. kar.ma Coffee\'s Boudha outlet is immediately next door.', location: 'Utpala Cafe, Pawo Gompa Marg, Dhara Tole, Boudha, Kathmandu 44600, Nepal', longDescription: 'Owned and run by the Ka-Nying Shedrub Ling monastery, known locally as the White Gompa, about three minutes\' walk off the Boudha kora. It has a big walled garden with its own parking, which almost nothing near the stupa has, and it is fully vegetarian with clear vegan labelling. Free wifi and plenty of power make it a genuine sit-down morning rather than a coffee stop.', priceHint: 'Coffee NPR 200-350; unlimited vegetarian buffet NPR 450' },
  { id: 'nf18', name: 'Coffee Beans Specialty Coffee', category: 'Café', description: 'A bright upstairs shophouse bar in Tushal that is the purest specialty coffee near Boudha and one of the highest-rated in the city - and indoors, so it is warm at 08:00 in December.', bestTime: '07:30-09:30, before or straight after a Boudha kora; it opens at 07:00', duration: '45-60 minutes', photoRating: 3, notes: 'Open 07:00-20:00 daily, 4.8 from roughly 490 Google reviews. One gotcha repeated in reviews: the house filter is around NPR 200 and the \'specialty\' lots around NPR 400, and staff do not always volunteer the difference - ask the price of the lot before you pick it. Free wifi, restroom, quiet soundtrack, a genuine slow-morning laptop spot. The Chabahil-Boudha-Jorpati road east toward Changu Narayan passes right by, so it also works on the 16th.', location: 'Coffee Beans - Specialty Coffee Shop, Tushal-6, Chabahil-Boudha-Jorpati Road, Dhara Tole, Boudha, Kathmandu 44600, Nepal', longDescription: 'Opened in 2017 and rated 4.8 across roughly 490 Google reviews, it roasts its own single-origin lots including anaerobic naturals and brews them as V60 and AeroPress, serving filter in a pot with handleless cups. It runs barista classes, so the staff can actually talk about what they poured you. It is the warm indoor counterpoint to Utpala\'s garden on the same Boudha morning.', priceHint: 'House filter about NPR 200; specialty single-origin pour-over about NPR 400' },
  { id: 'nf19', name: 'Chikusa Cafe', category: 'Café', description: 'One of Nepal\'s oldest dedicated coffee houses, open since 1998 and originally Japanese-run, with no espresso machine at all on purpose - everything is cloth-filter drip, moka pot or French press.', bestTime: '07:30-08:30 - it opens 07:30 and fills with regulars from about 08:00 to 11:00', duration: '45-60 minutes', photoRating: 4, notes: 'Open 07:30-20:00 daily, 4.4 from roughly 410 Google reviews with reviews as recent as the last month. NO ESPRESSO MACHINE - the menu word \'espresso\' means moka pot, so do not turn up wanting a flat white or latte art. Even the ice for iced coffee is frozen coffee so it never waters down. Food is made to order and slow by design. The front room is genuinely tight but there is a larger room at the back, and there is a smoking section. Cash is easiest and treat the wifi as unreliable. About 10 minutes\' walk from a Thamel hotel by the Garden of Dreams.', location: 'Chikusa Cafe, Amrit Marg, Jyatha, Thamel, Kathmandu 44600, Nepal (Plus Code P866+QR3)', longDescription: 'Open since 1998 and originally Japanese-run, Chikusa is a narrow diner bar where locals read the morning paper. Everything is brewed by cloth filter, moka pot or French press from local Nepali beans ground to order - there is deliberately no espresso machine on the premises. It is the anti-chain answer five minutes from a Thamel base, and it opens early enough to precede a Durbar Square morning.', priceHint: 'NPR 150-350 per cup; set breakfast about NPR 500-700' },
  { id: 'nf20', name: 'Pumpernickel Bakery', category: 'Café', description: 'A Thamel institution baking since 1986, with the best walled garden in the tourist quarter - and at 06:30 the earliest verified opening of any cafe on this list.', bestTime: '08:00-10:00, once the sun reaches the courtyard', duration: '45-75 minutes', photoRating: 3, notes: 'Open 06:30-21:30 daily, 4.4 from roughly 979 Google reviews - the only place here confirmed to be serving before 07:00, which is what makes it useful on the mornings you come back down from Nagarkot or Phulchowki early. The garden is genuinely cold before about 09:00 in mid-December, so start at an indoor table and move out when the sun arrives. Breakfast sets do not include a drink, so the bill runs higher than the menu suggests. Treat the wifi as unlisted. A 5-8 minute walk from a Thamel hotel beside the Garden of Dreams.', location: 'Pumpernickel Bakery, Paryatan Marg, Thamel, Kathmandu-26, Kathmandu 44600, Nepal', longDescription: 'Baking in Thamel since 1986. You queue at a bread-and-pastry counter at the front and walk through into a tree-shaded courtyard at the back, where half the city\'s trekkers eat breakfast - brown bread, croissants, cinnamon rolls and cooked breakfasts. There are indoor floors as well as the garden, which matters in December.', priceHint: 'NPR 400-800 for breakfast; coffee NPR 150-300' },
];

export const NEPAL_CATEGORIES = ['All', 'Must-Visit', 'Hidden Gem', 'Temple', 'Food', 'Café', 'Nature', 'Photography', 'Day Trip'];

// ── Japan guide content (moved byte-identically from the former lib/japan-data.ts) ──────────

export const JAPAN_ATTRACTIONS: Recommendation[] = [
  { id: 'ja1', image: '/images/japan/ja1.jpg', name: 'Senso-ji Temple', category: 'Must-See', description: 'Tokyo\'s oldest and most significant Buddhist temple. The Thunder Gate (Kaminarimon) and Nakamise shopping street are iconic.', bestTime: 'Early morning or night', duration: '2-3 hours', photoRating: 5, notes: 'Visit at dawn for empty shots. Night illumination is magical.', location: 'Asakusa, Tokyo', mustSee: true, longDescription: 'Founded in 645, Senso-ji is Tokyo\'s oldest temple and its most visited. You enter through the towering Kaminarimon ("Thunder Gate") with its giant red lantern, then walk the Nakamise-dori, a centuries-old shopping street of snack and souvenir stalls, up to the main hall and five-storey pagoda. It is free to enter, busy by day and beautifully lit after dark; the Asakusa district around it keeps an old-Tokyo, downtown feel.', priceHint: 'Free (grounds & main hall)' },
  { id: 'ja2', image: '/images/japan/ja2.jpg', name: 'Fushimi Inari Shrine', category: 'Must-See', description: 'Thousands of vermillion torii gates winding up a mountainside. One of the most photographed sites in Japan.', bestTime: 'Dawn or dusk', duration: '2-4 hours', photoRating: 5, notes: 'Go early to avoid crowds. Full hike to summit takes 2-3 hours. A 06:30 start is 30 minutes before sunrise in late December — the lower torii route is lit well enough to walk but not to shoot, and usable frames start around 06:50.', location: '68 Fukakusa Yabunouchicho, Fushimi Ward, Kyoto 612-0882', mustSee: true, longDescription: 'Fushimi Inari Taisha is the head shrine of Inari, the Shinto deity of rice and prosperity, and one of Japan\'s most iconic sights. Thousands of vermilion torii gates — donated by businesses — form tunnels that wind up the wooded slopes of Mt Inari. A full loop to the summit takes two to three hours; most visitors turn back at the Yotsutsuji intersection for the valley view. It is open 24 hours and free, so dawn visits reward you with empty gate tunnels.', priceHint: 'Free · open 24h' },
  { id: 'ja3', image: '/images/japan/ja3.jpg', name: 'Shibuya Crossing', category: 'Must-See', description: 'The world\'s busiest pedestrian crossing. Up to 3,000 people cross simultaneously. An icon of Tokyo\'s urban energy.', bestTime: 'Evening rush hour', duration: '1 hour', photoRating: 5, notes: 'Best viewed from Shibuya Sky observation deck or Starbucks.', location: 'Shibuya, Tokyo', mustSee: true, longDescription: 'Shibuya Scramble Crossing is the emblem of modern Tokyo — when the lights change, waves of pedestrians surge across from all directions at once beneath giant video screens. It is busiest around evening rush hour. For the classic overhead view, head up to the open-air Shibuya Sky observation deck atop Shibuya Scramble Square, or watch from the second-floor Starbucks in the Tsutaya building. The loyal-dog Hachiko statue stands just outside the station.' },
  { id: 'ja4', image: '/images/japan/ja4.jpg', name: 'Tokyo Tower', category: 'Must-See', description: 'A 333m communications tower with observation decks looking out over the city, especially good at night.', bestTime: 'Sunset to night', duration: '1.5 hours', photoRating: 5, notes: 'Winter nights offer the clearest views. Main deck 09:00-22:30, last entry 22:00, ¥1,500; the top deck is a timed tour worth booking online. The Jan 1 first-sunrise session is a queue for about sixty places from around 02:00, not a booking.', location: '4-2-8 Shibakoen, Minato-ku, Tokyo 105-0011', longDescription: 'Completed in 1958 and modelled on the Eiffel Tower, the 333-metre Tokyo Tower remains a beloved city landmark, painted white and international orange. It has a Main Deck at 150 m and a higher Top Deck at 250 m reached by a guided tour. Clear, dry winter nights give the sharpest city panoramas, and the tower is dramatically floodlit after dark — a favourite backdrop from the surrounding Minato streets.' },
  { id: 'ja5', image: '/images/japan/ja5.jpg', name: 'Mount Fuji Winter View', category: 'Scenic', description: 'Japan\'s iconic mountain is most visible in winter with snow-capped peak against clear blue skies.', bestTime: 'Clear morning', duration: 'Full day trip', photoRating: 5, notes: 'Lake Kawaguchiko offers best winter reflections. Not climbable in winter.', location: 'Yamanashi', mustSee: true, longDescription: 'Mount Fuji, a near-symmetrical volcano and UNESCO site, is most reliably visible in the cold, dry air of winter, its snow-capped cone rising against clear blue skies. The Fuji Five Lakes area in Yamanashi — especially Lake Kawaguchiko — offers the classic reflected view and the Chureito Pagoda vantage. The climbing season is summer only; winter is purely for viewing and photography from the lakes and surrounding towns.' },
  { id: 'ja6', image: '/images/japan/ja6.jpg', name: 'Akihabara Electric Town', category: 'Anime', description: 'Tokyo\'s electronics and anime paradise. Multi-floor arcades, manga shops, maid cafes, and figure stores.', bestTime: 'Afternoon to evening', duration: '3-5 hours', photoRating: 4, notes: 'Visit Super Potato for retro games. Don\'t miss the arcades.', location: 'Akihabara, Tokyo' },
  { id: 'ja7', image: '/images/japan/ja7.jpg', name: 'Kinkaku-ji (Golden Pavilion)', category: 'Must-See', description: 'Zen Buddhist temple covered in gold leaf, reflected in a mirror pond. Stunning in winter with occasional snow.', bestTime: 'Morning', duration: '1-2 hours', photoRating: 5, notes: 'Snow-covered Golden Pavilion is incredibly rare and beautiful. 09:00-17:00 daily, open every day of the year including Dec 29 - Jan 3. About 40 minutes from Arashiyama, so the two pair in one day with no slack.', location: '1 Kinkakujicho, Kita Ward, Kyoto 603-8361', mustSee: true, longDescription: 'Kinkaku-ji, the Golden Pavilion, is a Zen temple whose top two floors are entirely covered in gold leaf, mirrored in the still Kyoko-chi ("Mirror Pond") before it. Originally a shogun\'s retirement villa, the current structure is a 1955 reconstruction after arson. A one-way garden path leads past the pavilion and through mossy grounds. A rare dusting of snow on the golden roof is one of Japan\'s most coveted winter photographs.', priceHint: '¥500 entry' },
  { id: 'ja8', image: '/images/japan/ja8.jpg', name: 'TeamLab Borderless', category: 'Experience', description: 'Immersive digital art museum with ever-changing rooms of light, color, and interactive projections.', bestTime: 'Weekday afternoon', duration: '3 hours', photoRating: 5, notes: 'Book tickets in advance. Wear white for best photo effects.', location: 'Azabudai, Tokyo' },
  { id: 'ja9', image: '/images/japan/ja9.jpg', name: 'Meiji Shrine', category: 'Cultural', description: 'Serene Shinto shrine set in a lush forest in central Tokyo. A peaceful retreat from the urban bustle.', bestTime: 'Morning', duration: '1.5 hours', photoRating: 4, notes: 'Write a wish on an ema plaque. Gates follow sunrise and sunset — about 06:40-16:20 in early January. It takes roughly three million hatsumode visitors across Jan 1-3, with a marshalled queue of an hour or more; Hanazono Shrine in Shinjuku is the low-effort substitute.', location: '1-1 Yoyogikamizonocho, Shibuya-ku, Tokyo 151-8557' },
  { id: 'ja10', image: '/images/japan/ja10.jpg', name: 'Arashiyama Bamboo Grove', category: 'Must-See', description: 'A pathway winding through towering bamboo stalks. Winter lighting events add to the atmosphere.', bestTime: 'Early morning', duration: '2 hours', photoRating: 5, notes: 'Open access at any hour and unlit, so a 07:00 arrival in late December is pre-sunrise — the crowd argument holds until about 08:30. The December Hanatouro illumination has not run in its original form since 2021 and ended around Dec 19 even then; do not plan around it.', location: 'Chikurin-no-Komichi, Sagaogurayama Tabuchiyamacho, Ukyo Ward, Kyoto 616-8394', mustSee: true, longDescription: 'The Arashiyama Bamboo Grove is a short, atmospheric path where towering green bamboo stalks arch overhead and rustle in the wind. It sits in the scenic Arashiyama district of western Kyoto alongside Tenryu-ji temple, the Togetsukyo bridge over the Katsura River, and the Iwatayama monkey park. The grove is free and always open, so an early-morning visit before 8 AM is the only reliable way to photograph it without crowds.', priceHint: 'Free · open access' },
  { id: 'ja11', image: '/images/japan/ja11.jpg', name: 'Tsukiji Outer Market', category: 'Food', description: 'Vibrant food market with fresh sushi, seafood, tamagoyaki, and street food stalls. A food lover\'s paradise.', bestTime: 'Early morning', duration: '2-3 hours', photoRating: 4, notes: 'Come hungry, and come early — trade starts around 06:00 and many stalls shut by early afternoon. Closed Sundays and some Wednesdays, and shut Dec 31 - Jan 4, which leaves Dec 28-29 or Jan 5 onward on this trip.', location: '4-16-2 Tsukiji, Chuo-ku, Tokyo 104-0045' },
  { id: 'ja12', image: '/images/japan/ja12.jpg', name: 'Dotonbori', category: 'Food', description: 'Osaka\'s neon-lit food street famous for takoyaki, okonomiyaki, and giant crab signs. The heart of "Japan\'s Kitchen".', bestTime: 'Evening', duration: '3 hours', photoRating: 5, notes: 'Try Kukuru for takoyaki. Night reflections on the canal are stunning.', location: 'Namba, Osaka' },

  // Hidden Gems
  { id: 'ja13', image: '/images/japan/ja13.jpg', name: 'Yanaka Old Town', category: 'Hidden Gem', description: 'A rare survivor of old Tokyo with narrow lanes, wooden houses, temples, and a nostalgic shopping street (Yanaka Ginza). Escapes the tourist crowds.', bestTime: 'Late morning', duration: '2-3 hours', photoRating: 4, notes: 'Crisp winter light makes the low-rise streets glow. Try a menchi-katsu from Yanaka Ginza. Shops run roughly 10:00-18:00 and many close by dusk — sunset is around 16:35, so the light on the Yuyake Dandan steps lands mid-afternoon.', location: '3-13-1 Yanaka, Taito-ku, Tokyo 110-0001' },
  { id: 'ja14', image: '/images/japan/ja14.jpg', name: 'Golden Gai', category: 'Hidden Gem', description: 'A warren of six tiny alleys packed with over 200 minuscule themed bars, most seating only a handful of guests. Atmospheric, retro Showa-era Tokyo.', bestTime: 'Night', duration: '2 hours', photoRating: 4, notes: 'Most bars open around 19:00-20:00 and run until the last customer leaves. Seat charge ¥500-1,500 per person on top of drinks, and a good number will not take a group of three — read the door sign for both. Over New Year each bar sets its own break and none of it is published in advance.', location: '1-1-6 Kabukicho, Shinjuku-ku, Tokyo 160-0021' },
  { id: 'ja15', image: '/images/japan/ja15.jpg', name: 'Omoide Yokocho', category: 'Hidden Gem', description: 'Nicknamed "Memory Lane," a smoky lantern-lit alley of cramped yakitori and izakaya stalls under the Shinjuku train tracks. Pure atmospheric Tokyo.', bestTime: 'Evening', duration: '1-2 hours', photoRating: 5, notes: 'Steam rising off grills on a cold winter night is hugely photogenic. Cash is king here. Counters seat six to eight, so a walk-in trio at 18:30 gets split up or waits — plan on two stalls, not one.', location: '1-2 Nishishinjuku, Shinjuku-ku, Tokyo 160-0023' },
  { id: 'ja16', image: '/images/japan/ja16.jpg', name: 'Shimokitazawa', category: 'Hidden Gem', description: 'A bohemian, low-rise neighborhood of vintage clothing stores, indie record shops, tiny theaters, and third-wave coffee. Tokyo\'s relaxed creative side.', bestTime: 'Afternoon', duration: '3 hours', photoRating: 4, notes: 'Best explored on foot with no plan. Start at Mikan Shimokita, the five blocks of shops built into the arches under the station — vintage, records and kitchens side by side. The independent vintage shops around it are the category most likely to be shut Jan 1-3.', location: '2-11-15 Kitazawa, Setagaya-ku, Tokyo 155-0031' },

  // Seasonal Winter Attractions (Dec 19 - Jan 9 trip window)
  { id: 'ja17', image: '/images/japan/ja17.jpg', name: 'Nabana no Sato Winter Illumination', category: 'Winter', description: 'One of Japan\'s largest winter illuminations, with millions of LEDs forming tunnels of light and immersive seasonal light shows in a botanical garden.', bestTime: 'After sunset', duration: '2-3 hours', photoRating: 5, notes: 'Runs through winter into spring — peak season is December–January. The Tunnel of Lights is the signature shot.', location: 'Kuwana, Mie (near Nagoya)', longDescription: 'Nabana no Sato is a botanical garden near Nagoya famous for hosting one of Japan\'s largest and most elaborate winter illuminations. Millions of LEDs form the signature "Tunnel of Lights" and a huge themed light show that changes each season, running from autumn through to spring with December to January as the peak. Admission typically includes a garden voucher; go after sunset for the full effect.' },
  { id: 'ja18', image: '/images/japan/ja18.jpg', name: 'Hakone Onsen Ryokan', category: 'Winter', description: 'Soak in an open-air hot spring (rotenburo) surrounded by winter scenery, often with views toward Mount Fuji. The classic Japanese cold-weather ritual.', bestTime: 'Evening or early morning', duration: 'Overnight', photoRating: 4, notes: 'A steaming outdoor bath in cold December air is the quintessential winter experience. Many ryokan include kaiseki dinner.', location: 'Hakone, Kanagawa' },
  { id: 'ja19', image: '/images/japan/ja19.jpg', name: 'Gala Yuzawa Snow Resort', category: 'Winter', description: 'A ski-and-snow resort reachable directly by bullet train from Tokyo, with slopes, snow play areas, and guaranteed winter snow within a day trip.', bestTime: 'Daytime', duration: 'Full day', photoRating: 4, notes: 'The Gala Yuzawa shinkansen station connects straight to the gondola — walk from the platform to the rental counter to the lift without going outside. About 1h50 from the Shinjuku base via Tokyo Station. The bundled JR East day-trip plan (round-trip shinkansen plus lift pass) is much cheaper than buying separately and opens one month before the travel date. The 2026-27 season dates were unpublished as of September 2026; the gondola also stops in high wind and there is no other way up.', location: '1039-2 Yuzawa, Yuzawa-machi, Minamiuonuma-gun, Niigata 949-6101' },
  { id: 'ja20', image: '/images/japan/ja20.jpg', name: 'Shirakawa-go Winter Village', category: 'Winter', description: 'A UNESCO village of steep thatched-roof gassho-zukuri farmhouses, blanketed in deep snow and lit up on select winter evenings — a storybook scene.', bestTime: 'Dusk (light-up evenings)', duration: 'Full day trip', photoRating: 5, notes: 'The winter light-up events fall on limited January dates and require advance reservation. Snow can be waist-deep.', location: 'Shirakawa, Gifu' },
  { id: 'ja21', image: '/images/japan/ja21.jpg', name: 'Roppongi Hills Keyakizaka Illumination', category: 'Winter', description: 'A 400m avenue of zelkova trees draped in blue-and-white "Snow & Blue" LEDs, framed against Tokyo Tower — and the one winter light-up that is over before this trip reaches Tokyo.', bestTime: 'After dark, but not on these dates', duration: '1 hour', photoRating: 5, notes: 'Timing trap: the Keyakizaka season ends Dec 25 and the Tokyo leg starts Dec 27, so this is listed to rule it out rather than to plan. The two that do cover the whole stay are the Marunouchi Naka-dori lights (mid-November to mid-February) and the Tokyo Midtown Walkway of Light (into late February) — both free, both a short walk from stops already in the plan.', location: 'Roppongi, Tokyo' },

  // Anime & Gaming
  { id: 'ja22', image: '/images/japan/ja22.jpg', name: 'Nakano Broadway', category: 'Anime', description: 'A retro multi-floor mall that is a treasure trove for collectors — vintage manga, rare figures, cels, and the original Mandarake flagship. Quieter than Akihabara.', bestTime: 'Afternoon', duration: '2-3 hours', photoRating: 4, notes: 'Less touristy than Akihabara and better for rare/vintage finds. The basement has cult dessert shop Daily Chiko. Building 10:00-20:00 but most collector shops only open at 12:00, and the two dozen Mandarake shopfronts inside each specialise — cels, Showa-era toys, out-of-print figures. Individual shops set their own New Year closures, so the collector floors are thin Jan 1-2.', location: '5-52-15 Nakano, Nakano-ku, Tokyo 164-0001' },
  { id: 'ja23', image: '/images/japan/ja23.jpg', name: 'Pokémon Center Mega Tokyo', category: 'Anime', description: 'The flagship Pokémon store packed with exclusive plush, apparel, and merchandise, with life-size character displays and limited regional goods.', bestTime: 'Weekday', duration: '1 hour', photoRating: 3, notes: 'On the 2F of the Alpa mall inside Sunshine City, with a card-game gym attached. 10:00-20:00; Sunshine City runs 11:00-19:00 on Jan 1 and is back to normal Jan 2-3, which is when the lucky-bag crowds arrive.', location: 'Sunshine City Alpa 2F, 3-1-2 Higashi-Ikebukuro, Toshima-ku, Tokyo 170-8630' },
  { id: 'ja24', image: '/images/japan/ja24.jpg', name: 'Ghibli Museum', category: 'Anime', description: 'A whimsical museum dedicated to Studio Ghibli, with original art, a rooftop robot soldier, a mini theater of exclusive shorts, and dreamlike architecture.', bestTime: 'Morning slot', duration: '2-3 hours', photoRating: 4, notes: 'Advance reservation only — no walk-ins, no door sales. Tickets go on sale at 10:00 JST on the 10th of the preceding month and routinely sell out the same morning, so a January visit means being online on Dec 10. Entry slots at 10:00, 12:00, 14:00 and 16:00; closed Tuesdays, plus a year-end and New Year closure. No photos indoors.', location: '1-1-83 Shimorenjaku, Mitaka-shi, Tokyo 181-0013', priceHint: '¥1,000 adults' },
  { id: 'ja25', image: '/images/japan/ja25.jpg', name: 'GiGO Akihabara Arcade', category: 'Anime', description: 'A towering multi-floor game arcade with claw machines, rhythm games, retro cabinets, and gachapon. Pure neon-lit Japanese gaming culture.', bestTime: 'Evening', duration: '1-2 hours', photoRating: 4, notes: 'Building 3 is the one with the RETRO:G floor of 1990s cabinets — Daytona, OutRun, Super Street Fighter II — and the latest closing time in the district at 23:30. Bring a stack of 100-yen coins. Arcades are among the few Akihabara venues reliably open across Jan 1-3. Under-16s are not admitted after 18:00.', location: '1-11-11 Sotokanda, Chiyoda-ku, Tokyo 101-0021' },

  // Shopping Districts
  { id: 'ja26', image: '/images/japan/ja26.jpg', name: 'Ginza Shopping District', category: 'Shopping', description: 'Tokyo\'s most upscale shopping quarter — flagship department stores, luxury boutiques, and the giant Ginza Six and Uniqlo flagships, dressed up for the holidays.', bestTime: 'Afternoon to evening', duration: '3 hours', photoRating: 4, notes: 'Weekend afternoons the main avenue becomes a car-free pedestrian "Hokoten." December window displays are spectacular. Ginza Six has a free 4,000 sq m rooftop garden open 07:00-23:00 with Tokyo Tower and the Skytree both visible — a genuine viewpoint without paying for another observation deck. The department stores shut Jan 1 and reopen Jan 2 with fukubukuro lucky bags.', location: '6-10-1 Ginza, Chuo-ku, Tokyo 104-0061' },
  { id: 'ja27', image: '/images/japan/ja27.jpg', name: 'Shinsaibashi & Amerikamura', category: 'Shopping', description: 'Osaka\'s buzzing covered shopping arcade and adjacent youth-fashion district — endless boutiques, drugstores, and streetwear under one long roofed street.', bestTime: 'Afternoon', duration: '2-3 hours', photoRating: 4, notes: 'The covered arcade is a perfect rainy- or cold-day option. Connects straight into Dotonbori for dinner.', location: 'Chuo, Osaka' },

  // — Osaka boys-trip additions (Universal Studios Japan, Den Den Town, Osaka Castle, Kyoto Manga Museum)
  { id: 'ja28', image: '/images/japan/ja28.png', name: 'Universal Studios Japan / Super Nintendo World', category: 'Experience', description: 'Osaka\'s big theme park, anchored by the immersive Super Nintendo World — a Mario Kart ride, Bowser\'s Castle, and interactive power-up bands. A full-day anchor for the Osaka leg.', bestTime: 'Full day, arrive at opening', duration: 'Full day', photoRating: 4, notes: 'Prioritize an Express Pass and check current anime/game collaborations closer to the date.', location: 'Universal Studios Japan, Konohana, Osaka' },
  { id: 'ja29', image: '/images/japan/ja29.jpg', name: 'Den Den Town / Nipponbashi', category: 'Anime', description: 'Osaka\'s anime and electronics district — a strip of multi-floor shops for figures, retro games, and collectibles. Quieter and less crowded than Tokyo\'s Akihabara.', bestTime: 'Afternoon', duration: '2-3 hours', photoRating: 3, notes: 'Look for One Piece, Naruto and Dragon Ball Z figures and collectibles across the specialty shops.', location: 'Nipponbashi, Osaka' },
  { id: 'ja30', image: '/images/japan/ja30.jpg', name: 'Osaka Castle', category: 'Must-See', description: 'A grand reconstructed feudal keep ringed by moats and a park of plum and cherry trees, with a panoramic observation deck on top.', bestTime: 'Morning', duration: '2 hours', photoRating: 4, notes: 'The grounds and moat are quiet and crisp in winter; the museum inside covers the castle\'s history.', location: 'Chuo, Osaka' },
  { id: 'ja31', image: '/images/japan/ja31.jpg', name: 'Kyoto International Manga Museum', category: 'Anime', description: 'A converted 1920s elementary school housing 300,000+ manga volumes across every genre, plus rotating exhibits — a relaxed indoor pick on a recovery day.', bestTime: 'Afternoon', duration: '2-3 hours', photoRating: 3, notes: 'Hard date trap: the museum\'s own calendar closes it 2026/12/26 - 2027/1/6, so Dec 24 and Dec 25 are the only days of the Kyoto leg it is open. 10:00-17:00, last admission 16:30, closed Wednesdays. Most manga is Japanese-only; a smaller shelf holds translated and foreign works.', location: 'Karasuma-dori Oike-agaru, Nakagyo Ward, Kyoto 604-0846', priceHint: '¥1,200 adults' },

  // — Kyoto: the sights the day plan already names but the guide never carded
  { id: 'ja32', image: '/images/japan/ja32.jpg', name: 'Kiyomizu-dera', category: 'Must-See', description: 'A hillside temple founded in 780 above the Otowa waterfall, best known for the wooden stage that projects out over the valley on a lattice of pillars.', bestTime: 'Opens 06:00 — the one major Kyoto sight you can be inside before sunrise', duration: '1.5-2 hours', photoRating: 5, notes: 'Winter closing about 18:00, and it has no closing days at all. Special night viewings are spring and autumn only, so there is nothing to book in December. Sannenzaka and Ninenzaka run downhill from the gate towards Gion, which makes this the natural start of the Higashiyama walk rather than a stop in the middle of it.', location: '1-294 Kiyomizu, Higashiyama Ward, Kyoto 605-0862', mustSee: true, longDescription: 'The main hall sits on a stage 13 m above the hillside, held up by 168 pillars joined without a single nail, and looks back across the valley to central Kyoto. Below it the Otowa waterfall splits into three channels that visitors queue to drink from. The temple opens at 06:00 every day of the year — two hours before almost anything else in Kyoto — so it is the better dawn target than Fushimi Inari if the group would rather shoot in usable light than walk uphill with a torch.', priceHint: '¥500 adults' },
  { id: 'ja33', image: '/images/japan/ja33.jpg', name: 'Nijo Castle', category: 'Cultural', description: "The shogun's Kyoto residence, finished in 1603, ringed by two moats and entered through the carved Karamon gate. The draw is the Ninomaru Palace interior with its nightingale floors and Kano-school screen paintings.", bestTime: 'Morning', duration: '2 hours', photoRating: 4, notes: 'The December trap on this one is real: Ninomaru-goten closes every Tuesday in December and again Dec 26-28, and the grounds themselves close Dec 29-31. For a Kyoto leg running Dec 24-27 that means the palace interior on Dec 24 or Dec 25 only, and grounds-only on Dec 26. Castle 08:45-17:00, last entry 16:00; Ninomaru reception closes 16:10. Without the palace interior this is a walk around a moat.', location: '541 Nijojocho, Nijo-dori Horikawa-nishi-iru, Nakagyo Ward, Kyoto 604-8301', priceHint: '¥800 castle; ¥1,300 with Ninomaru Palace; Honmaru Palace a further ¥1,000 by advance reservation' },
  { id: 'ja34', image: '/images/japan/ja34.jpg', name: 'Tenryu-ji', category: 'Cultural', description: 'The head temple of its Rinzai branch, whose Sogenchi pond garden keeps a fourteenth-century layout and borrows the Arashiyama hills as its backdrop. The bamboo grove path starts directly behind it.', bestTime: 'From 08:30, straight after the grove', duration: '1-1.5 hours', photoRating: 4, notes: 'The Cloud Dragon painted on the Hatto ceiling is a separate ticket and only opens to the public at weekends and on holidays outside special periods — Dec 26 2026 is a Saturday, so it is open; moving the Arashiyama day to a weekday loses it. The hall is closed to the public on Jan 2. Garden open year round, 08:30-17:00, last admission 16:50.', location: '68 Sagatenryuji Susukinobabacho, Ukyo Ward, Kyoto 616-8385', priceHint: '¥500 garden; ¥800 garden plus buildings; Cloud Dragon a separate ¥500' },
  { id: 'ja35', image: '/images/japan/ja35.jpg', name: 'Arashiyama Monkey Park Iwatayama', category: 'Experience', description: 'About 120 wild Japanese macaques on the hillside above the Katsura River, reached by a 15-20 minute climb. Feeding happens from inside a caged hut at the top, with the humans in the cage and the monkeys outside it.', bestTime: 'Late morning', duration: '1.5 hours including the climb', photoRating: 4, notes: 'Winter hours are 09:00-16:00 and the 16:00 close is what caps how late an Arashiyama morning can run. Cash at the gate, no advance tickets, monkey food is ¥100 at the top and bringing your own is banned. Closes in heavy rain or snow, and usually for a few days around Jan 1. The summit clearing is the widest open view over Kyoto anywhere in the city.', location: '61 Arashiyama Nakaoshitacho, Nishikyo Ward, Kyoto 616-0007' },
  { id: 'ja36', image: '/images/japan/ja36.jpg', name: 'Nishiki Market', category: 'Shopping', description: 'A covered arcade five blocks long holding about a hundred stalls — pickles, yuba, knives, dried seafood and skewered snacks eaten standing up.', bestTime: 'Late morning to mid-afternoon', duration: '1-2 hours', photoRating: 4, notes: 'Hours run store by store, typically 10:00-18:00, and a good number close on Wednesdays. The near end is 350 m from Shijo-Kawaramachi, which makes it the default filler block on the Kyoto arrival afternoon. Its busiest week is Dec 28-31 when Kyoto shops for osechi, and most stalls then close Jan 1-4.', location: 'Nishikikoji-dori between Teramachi-dori and Takakura-dori, Nakagyo Ward, Kyoto 604-8054', priceHint: '¥200-800 a snack' },
  { id: 'ja37', image: '/images/japan/ja37.jpg', name: 'Kyoto Station Building and Kyoto Tower', category: 'Scenic', description: "Hara Hiroshi's 1997 station building is a 470 m glass-and-steel canyon with a 171-step staircase that runs an LED light show through the evening, a rooftop Skyway walk, and a ramen floor on 10F. The tower across the road puts a deck at 100 m.", bestTime: 'Evening', duration: '1-2 hours', photoRating: 4, notes: 'The Daikaidan staircase show and the Skyway are both free, which makes this the cheapest way to fill an arrival or departure afternoon in a city that caps building heights. Tower deck 10:00-21:00, last entry 20:30. Kyoto Ramen Koji on 10F runs roughly 11:00-22:00. Building and tower both stay open across New Year; individual restaurants inside vary.', location: '721-1 Higashishiokojicho, Shimogyo Ward, Kyoto 600-8216', priceHint: '¥900 tower deck; staircase and Skyway free' },

  // — Kansai day trips. Nara is the shortest real one on the whole trip at about 1h15 door to door.
  { id: 'ja38', image: '/images/japan/ja38.jpg', name: 'Todai-ji and Nara Park', category: 'Day Trip', description: "The world's largest wooden temple hall, holding a 15m bronze Buddha cast in 752, at the top of a park where the deer walk up the approach path to meet you.", bestTime: 'Leave Osaka around 09:00; everything outdoors has to be done by 16:00 for the light', duration: 'Full day', photoRating: 5, notes: 'Osaka-Namba to Kintetsu-Nara is 35-38 minutes on a Rapid Express with no transfer and six trains an hour, and no reservation is needed — only the Limited Express takes one. The hall is a 20-minute walk from the station. Open 08:00-17:00 Nov-Mar with no closing days. Nara Park is free; the hall is charged.', location: '406-1 Zoshicho, Nara, Nara 630-8587', mustSee: true, longDescription: 'The Daibutsuden is the largest wooden building of its kind, and the current hall is only two thirds the width of the original. Inside, the Great Buddha sits 15 m high in bronze cast in 752; one of the supporting pillars has a hole through it the size of the statue\'s nostril that people squeeze through for luck. The approach runs through the Nandaimon gate under two 8 m guardian figures carved in 1203, and the deer that wander the park are treated as messengers of the shrine next door rather than as wildlife. Door to door from Shinsaibashi is about 1h15 — the shortest real day trip available on this trip.', priceHint: '¥800 for the hall; the park is free' },
  { id: 'ja39', image: '/images/japan/ja39.jpg', name: 'Himeji Castle', category: 'Day Trip', description: 'The only large Japanese castle that came through the wars and the fires intact — 83 original wooden structures around a six-floor keep, white-plastered and visible from the station down a straight 1km avenue.', bestTime: 'Leave before midday; last admission is 16:00 with no re-entry', duration: 'Full day', photoRating: 5, notes: 'JR Osaka to Himeji is 62-64 minutes on a Special Rapid, then a 20-minute walk; about 1h50 door to door from Shinsaibashi including the subway to Umeda. 09:00-17:00 Sep-Apr. Closed Dec 29-30, its only two closing days of the year. You climb the keep in socks on the original stairs. A timed e-ticket skips the booth queue but no reservation is required. Ticket prices have moved recently — check before budgeting.', location: '68 Honmachi, Himeji, Hyogo 670-0012', longDescription: 'Himeji survived the sixteenth-century wars, the Meiji demolition of the castles, the 1945 firebombing and the 1995 earthquake, which is why it is the reference point for what a Japanese castle actually looked like. The keep is a six-floor timber structure inside white plaster walls, and the approach spirals through a deliberately confusing sequence of gates and blind courtyards designed to break an attack. Winter is its quietest season, and the bare trees open up the sightlines from the outer baileys.' },
  { id: 'ja40', image: '/images/japan/ja40.jpg', name: 'Byodo-in, Uji', category: 'Day Trip', description: 'The Phoenix Hall of 1053, one of the few original Heian-period wooden buildings still standing, mirrored in the pond of its Pure Land garden. It is the building on the back of the ten-yen coin.', bestTime: 'Morning', duration: 'Half day', photoRating: 5, notes: 'The only genuine half-day trip from a Kyoto base. Keihan Gion-Shijo is five minutes over Shijo bridge from Kawaramachi, then 30-35 minutes to Keihan Uji with a change at Chushojima and a 15-minute walk — under an hour door to door, so it fits a morning without displacing an evening. Garden 08:45-17:30. Phoenix Hall interior tours run 09:30-16:10, every 20 minutes, 50 people a slot, sold same-day at the garden reception — get the slot on arrival, because on busy days reception closes before 16:10.', location: '116 Ujirenge, Uji, Kyoto 611-0021', priceHint: '¥700 garden and museum; ¥300 extra for the Phoenix Hall interior' },
  { id: 'ja41', image: '/images/japan/ja41.jpg', name: 'Kobe Nunobiki Herb Gardens and Ropeway', category: 'Day Trip', description: 'A ten-minute glass-sided gondola from a base station five minutes from Shin-Kobe, climbing over Nunobiki Falls to terraced gardens and a viewing deck with the city and the harbour directly below.', bestTime: 'Late afternoon into dark', duration: 'Half day', photoRating: 4, notes: 'The cheapest big view on the Kansai leg, and it works after dark — which matters when the sun is down by 16:52. Shinsaibashi to Shin-Kobe is about 1h05: subway to Osaka Station, JR Special Rapid to Sannomiya, one subway stop. Winter hours 09:30-16:45. The one window where every garden area is open and the evening illumination runs ends Dec 25; from Dec 26 only the top observatory area opens. The ropeway also stops for wind, so keep the Kitano lanes below it as the fallback.', location: '1-4-3 Kitanocho, Chuo-ku, Kobe, Hyogo 650-0002' },
  { id: 'ja42', image: '/images/japan/ja42.jpg', name: 'Osaka Aquarium Kaiyukan', category: 'Experience', description: 'A spiral-descent aquarium built around a 9m-deep central Pacific tank holding whale sharks. The Tempozan ferris wheel and the harbour ferry terminal are on the same quay.', bestTime: 'Afternoon', duration: '2.5-3 hours', photoRating: 4, notes: 'Shinsaibashi to Osakako is about 30 minutes on two subway lines and the aquarium is five minutes from the exit, so it is the one Osaka outing that survives a late start after a heavy night. Indoors, which matters on a cold December afternoon. Broadly 10:00-20:00 with real seasonal variation and a per-date calendar — check the day rather than assuming. Buy a timed e-ticket; the gate queue on a holiday afternoon is long.', location: '1-1-10 Kaigandori, Minato-ku, Osaka 552-0022' },

  // — Tokyo: the anchors the day plan leans on. Booking windows are the actionable part of most of these.
  { id: 'ja43', image: '/images/japan/ja43.jpg', name: 'Tokyo Skytree', category: 'Must-See', description: "At 634 m the tallest structure in Japan, with a deck at 350 m and a spiral galleria ramp at 450 m. It stands on the east bank of the Sumida, so the view looks back across the whole city rather than out from the middle of it.", bestTime: 'A slot around 15:30-16:30 buys daylight, sunset and night on one ticket', duration: '2 hours', photoRating: 5, notes: '10:00-21:00, last entry 20:00, extended in peak periods. Timed online tickets are cheaper than the counter and skip the queue. Cold, dry December air gives the sharpest panorama of the year. The separate Jan 1 first-sunrise session runs 05:30-07:30 for roughly 800 places, goes on sale around Dec 1 and sells out. Solamachi, the mall underneath, runs 10:00-21:00 and holds the JUMP SHOP.', location: '1-1-2 Oshiage, Sumida-ku, Tokyo 131-0045', mustSee: true, priceHint: 'Tembo Deck from ¥1,800; Tembo Galleria a further ¥1,400' },
  { id: 'ja44', name: 'JUMP SHOP Tokyo Solamachi', category: 'Anime', description: 'The official Shonen Jump store on the souvenir floor of the mall at the base of the Skytree — One Piece, Naruto, Dragon Ball, Jujutsu Kaisen and the rest of the roster, much of it shop-exclusive.', bestTime: 'Same trip as the Skytree', duration: '45 minutes', photoRating: 3, notes: 'This is the single shop that matches the One Piece / Naruto / Dragon Ball list exactly, and it is directly under the tower. 4F East Yard, on Solamachi building hours of 10:00-21:00. Solamachi runs fukubukuro lucky bags Jan 1-2 and keeps holiday hours over New Year, though individual shops can shorten.', location: 'Tokyo Skytree Town Solamachi 4F East Yard, 1-1-2 Oshiage, Sumida-ku, Tokyo 131-0045' },
  { id: 'ja45', image: '/images/japan/ja45.jpg', name: 'Ameya-Yokocho (Ameyoko)', category: 'Shopping', description: 'A few hundred metres of open-fronted stalls packed under and beside the elevated railway between Ueno and Okachimachi — dried seafood, fruit, sneakers, spices and cheap clothing, shouted at volume.', bestTime: 'Afternoon', duration: '1.5 hours', photoRating: 4, notes: 'Loud, cheap and shoulder-to-shoulder, a few minutes from Ueno Park. Most stalls 10:00-19:00, bars and standing counters later. The last week of December is its loudest of the year — vendors shout down the price of crab and osechi ingredients and the lane is close to impassable, which is exactly the reason to go then. Most stalls close Jan 1 and reopen Jan 2-4. The Ameyoko Center Building basement is a Southeast and East Asian grocery.', location: 'Ameyoko Center Building, 4-7-8 Ueno, Taito-ku, Tokyo 110-0005', priceHint: '¥300-800 a portion of street food' },
  { id: 'ja46', image: '/images/japan/ja46.jpg', name: 'Tokyo National Museum', category: 'Cultural', description: "Japan's oldest and largest museum, at the north end of Ueno Park across five buildings. The Honkan covers Japanese art from prehistory to the nineteenth century; the Gallery of Horyuji Treasures is the quiet one.", bestTime: 'Friday or Saturday, when it runs to 20:00', duration: '2-3 hours', photoRating: 3, notes: 'The indoor fallback for the Ueno day when it is dark by 16:35. 09:30-17:00, to 20:00 Fridays and Saturdays, closed Mondays. Two hard dates: it has published a year-end closure of Dec 26-31 2026, and Jan 4 is a Monday. Jan 2 is a Saturday and open until 20:00. The New Year display of that year\'s zodiac animal from the collection is a genuine January-only thing.', location: '13-9 Ueno Park, Taito-ku, Tokyo 110-8712', priceHint: '¥1,000 adults for the collection galleries; special exhibitions extra' },
  { id: 'ja47', image: '/images/japan/ja47.jpg', name: 'Super Potato Akihabara', category: 'Anime', description: 'Three floors of second-hand console games stacked to the ceiling — Famicom, Super Famicom, Mega Drive, Saturn, boxed and loose. The fifth floor is a free-to-browse retro arcade with a throne built out of Famicom shells.', bestTime: 'Afternoon', duration: '1 hour', photoRating: 4, notes: 'Roughly 11:00-20:00 daily. It is up a side alley off Chuo-dori and easy to walk straight past — the building is the one to navigate to, not the street. Independent Akihabara shops commonly close Jan 1 and sometimes through Jan 3; the big chains stay open.', location: 'Kitabayashi Building 3F-5F, 1-11-2 Sotokanda, Chiyoda-ku, Tokyo 101-0021' },
  { id: 'ja48', name: 'Mandarake Complex Akihabara', category: 'Anime', description: 'Eight floors of second-hand otaku goods, one category per floor — figures, cels, doujinshi, retro games on the sixth, toys and Gundam kits at the top.', bestTime: 'Afternoon', duration: '1.5-2 hours', photoRating: 4, notes: 'The deepest back-catalogue of Dragon Ball, Naruto and One Piece figures in Akihabara, and the floor-per-category layout means three people can split up and meet at the lift. 12:00-20:00 daily, buy-back counter closes 19:30. Listed as open 365 days, but confirm Jan 1 before making it the anchor of a day. A second Akihabara branch opened a short walk away in 2026.', location: '3-11-12 Sotokanda, Chiyoda-ku, Tokyo 101-0021' },
  { id: 'ja49', image: '/images/japan/ja49.jpg', name: 'Akihabara Radio Kaikan', category: 'Anime', description: 'Ten floors of specialist tenants directly outside the Electric Town exit — figure dealers, garage-kit makers, trading cards on the ninth, and a top-floor event space that runs anime pop-ups.', bestTime: 'Afternoon', duration: '1-1.5 hours', photoRating: 3, notes: 'One building, one lift, ten floors of figures — the fastest way to cover ground on a cold day, and the pop-up floor is where limited Jump collaborations land. Most shops 10:00-20:00, a few tenants later. Tenant hours vary over the holiday and some floors close Jan 1; the building also shuts entirely one or two days a year for statutory equipment inspection, announced in advance.', location: '1-15-16 Sotokanda, Chiyoda-ku, Tokyo 101-0021' },
  { id: 'ja50', image: '/images/japan/ja50.jpg', name: 'animate Ikebukuro Main Store', category: 'Anime', description: "Nine floors above ground and two below of manga, character goods, an event hall and a theatre, five minutes from Ikebukuro Station's east exit. Rebuilt in 2023 and recognised as the world's largest anime shop the year after.", bestTime: 'Any afternoon; Jan 2 is its busiest day of the year', duration: '1.5-2 hours', photoRating: 3, notes: 'The One Piece, Naruto and Dragon Ball shelves in one building rather than spread across Akihabara. 10:00-21:00. It shortens hours or closes around Jan 1 and restarts Jan 2 with lucky bags — that is the biggest day of its year, and worth taking on deliberately or avoiding deliberately.', location: '1-20-7 Higashi-Ikebukuro, Toshima-ku, Tokyo 170-0013' },
  { id: 'ja51', name: 'teamLab Planets TOKYO', category: 'Experience', description: 'A barefoot digital-art museum where you wade through knee-deep water, cross a mirrored floor and lie under a projected garden.', bestTime: 'Any timed slot; it runs to 22:00', duration: '2 hours', photoRating: 5, notes: 'Planets in Toyosu is the barefoot water venue and the more photogenic of the two teamLab sites — Borderless at Azabudai is the other, a different ticket in a different district. 09:00-22:00, last entry 21:00. Date-and-time tickets release roughly two months out and holiday slots sell out. It closes for maintenance on scattered single weekdays published only on its own calendar, so check the specific date. Mirrored floors and knee-deep water: trousers that roll above the knee, and skirts are a bad idea. It is open on Jan 1, which makes it one of the few New Year options.', location: '6-1-16 Toyosu, Koto-ku, Tokyo 135-0061', priceHint: 'Adults from ¥3,600' },
  { id: 'ja52', image: '/images/japan/ja52.jpg', name: 'Toyosu Market', category: 'Experience', description: 'The wholesale fish market that replaced the Tsukiji inner market, built as three sealed blocks with a public walkway threaded above the trading floors.', bestTime: 'Be there by 05:00 or there is no point going', duration: '3 hours including the travel', photoRating: 4, notes: 'Two tiers of access. The second-floor observation windows are free and need nothing — turn up by 05:00, the tuna auction runs roughly 05:30-06:30. The lower deck, one pane of glass from the floor, is a free lottery of about 100 places a day; applications open for roughly a week in the first week of the preceding month, and names must match passports, so a January visit means applying in the first week of December. 05:00-17:00 on market days, closed Sundays, holidays and scheduled Wednesdays, and shut roughly Dec 31 - Jan 4. The January 2027 market calendar was unpublished as of September 2026. Dress for a refrigerated hall, and do not pair a 05:00 start with a club night.', location: '6-6-1 Toyosu, Koto-ku, Tokyo 135-0061' },
  { id: 'ja53', image: '/images/japan/ja53.jpg', name: 'Warner Bros. Studio Tour Tokyo', category: 'Experience', description: 'A walk-through studio attraction on the site of the former Toshimaen amusement park, with standing sets, props and costumes from the Harry Potter films. Self-paced, and most visitors take four hours or more.', bestTime: 'An early slot — allow four hours minimum', duration: '4-5 hours', photoRating: 4, notes: 'Timed entry, non-refundable, no re-entry once inside, and January is peak. Tickets are also sold at the onsite office but pre-booking is the only sane approach for a New Year week — book as soon as the January 2027 calendar opens. Entry slots run from 08:30 into the evening and vary by season, so read the official opening-times calendar for the date before building anything else around it.', location: '1-1-7 Kasugacho, Nerima-ku, Tokyo 179-0074', priceHint: '¥6,600-7,300 adult depending on date' },
  { id: 'ja54', image: '/images/japan/ja54.jpg', name: 'Tokyo DisneySea', category: 'Day Trip', description: 'A nautically themed park built around a harbour and a working volcano. The Fantasy Springs area, opened in 2024, adds Frozen, Tangled and Peter Pan lands at the back of the site.', bestTime: 'Full day, arrive at opening', duration: 'Full day', photoRating: 4, notes: 'The ticketing is the part that goes wrong: sold online only with no gate sales, date-locked to one park with no hopper, and released daily at 14:00 JST for the same date two months ahead. The daily operating calendar for a month is only published around the 8th of the previous month, so hours appear well after the tickets do. Maihama back to Shinjuku is about 55 minutes, so a 21:00 close puts the group at the base around 22:15.', location: '1-13 Maihama, Urayasu, Chiba 279-0031', priceHint: 'One-day passport roughly ¥7,900-10,900 depending on date' },
  { id: 'ja55', image: '/images/japan/ja55.jpg', name: 'Shibuya Sky', category: 'Scenic', description: 'An open rooftop at 229 m directly above Shibuya Station, with the scramble crossing laid out below and Mt Fuji on the western horizon on a clear day.', bestTime: 'The slot straddling sunset — about 15:40-16:00 in late December', duration: '1.5 hours', photoRating: 5, notes: 'The booking window is the whole problem: slots open exactly 14 days ahead at 00:00 Japan time and sunset slots go within minutes. 10:00-22:30, last entry 21:20, entry every 20 minutes from the 14F counter. The rooftop closes in high wind or rain with no refund for the view — only the indoor 46th floor stays open. Dec 31 is shortened to 10:00-21:00, Jan 1 is closed to normal visitors apart from a separate paid sunrise session, and Jan 2 onward is normal.', location: 'Shibuya Scramble Square, 2-24-12 Shibuya, Shibuya-ku, Tokyo 150-6145', mustSee: true, priceHint: '¥2,600-3,000 booked online' },
  { id: 'ja56', image: '/images/japan/ja56.jpg', name: 'Tokyo Metropolitan Government Observation Decks', category: 'Scenic', description: 'Two free observation decks at 202 m reached by a dedicated lift, and after dark the tower\'s face becomes the screen for a free 15-minute projection-mapping show that repeats through the evening.', bestTime: 'Late afternoon into the evening projection slots', duration: '1.5 hours', photoRating: 4, notes: 'Free, walk-up, no booking, and a 15-minute walk from Kabukicho. South deck 09:30-22:00, north deck 09:30-17:30. The decks close Dec 29-31 and Jan 2-3 but open on Jan 1, and on Jan 1 only the south deck runs — inside this trip that makes Jan 1 the only date in the whole Dec 29 - Jan 3 stretch you can go up. The Jan 1 first-sunrise opening is a lottery, not a queue. The projection mapping outside is unaffected by any of it and runs roughly 17:30-21:45 on a rotating programme that has included Godzilla, Gundam and Pokemon pieces.', location: '2-8-1 Nishi-Shinjuku, Shinjuku-ku, Tokyo 163-8001', priceHint: 'Free' },
  { id: 'ja57', image: '/images/japan/ja57.jpeg', name: 'Hanazono Shrine', category: 'Cultural', description: 'The shrine that has watched over Shinjuku since before the town existed, in a walled compound on Meiji-dori three minutes from Golden Gai. The grounds are open around the clock and cost nothing.', bestTime: 'Before 09:00 on Jan 1-3 if hatsumode is the point', duration: '30-45 minutes', photoRating: 3, notes: 'The hatsumode option that is 200 m from the bars instead of an hour of queueing at Meiji Jingu. It runs a full New Year with food stalls and lit grounds Jan 1-3 and gets genuinely busy, but queues for the main hall are shortest before about 09:00. Office and charm counter roughly 09:00-17:00; the grounds never close.', location: '5-17-3 Shinjuku, Shinjuku-ku, Tokyo 160-0022', priceHint: 'Free' },
  { id: 'ja58', image: '/images/japan/ja58.jpg', name: 'Tokyo Midtown Walkway of Light', category: 'Winter', description: 'A lit walkway along the tree-lined garden path behind Roppongi, with an outdoor rink beside it. Free, and it runs into late February rather than stopping at Christmas.', bestTime: '17:00-23:00', duration: '1 hour', photoRating: 4, notes: 'This is the Roppongi winter lighting still running while the group is in town — the Keyakizaka illumination that gets recommended everywhere ends Dec 25, two days before they arrive. Shops 11:00-21:00, restaurants to 23:00, walkway 17:00-23:00. The ice rink is closed on Jan 1 only.', location: '9-7-1 Akasaka, Minato-ku, Tokyo 107-0052', priceHint: 'Free to walk; the rink is charged separately' },

  // — Day trips out of the Tokyo base. Hakone belongs before New Year: Jan 2-3 are the road-race
  // days and the national return-travel peak on top of each other.
  { id: 'ja59', image: '/images/japan/ja59.jpg', name: 'Hakone Open-Air Museum', category: 'Day Trip', description: 'A 70,000 sq m hillside sculpture park with a Picasso pavilion and a stained-glass tower you climb from inside. Most of the work stands outdoors against the mountains, and there is a free foot-onsen at the far end.', bestTime: 'Late morning, on the way round the Hakone loop', duration: '2-3 hours within a full day', photoRating: 5, notes: 'The concrete anchor a generic Hakone plan lacks. Ten minutes on foot from the Shinjuku base to Odakyu Shinjuku, 80-85 minutes on the Romancecar to Hakone-Yumoto, then about 40 minutes on the Tozan switchback to Chokoku-no-Mori — roughly 2h20 door to door. Open 09:00-17:00 every day of the year, and being half indoors it survives bad weather better than the ropeway leg. Romancecar seats are all reserved and open one month ahead.', location: '1121 Ninotaira, Hakone-machi, Ashigarashimo-gun, Kanagawa 250-0493', priceHint: 'About ¥2,000 adult; the Hakone Freepass gives a discount' },
  { id: 'ja60', image: '/images/japan/ja60.jpg', name: 'Owakudani', category: 'Day Trip', description: 'A sulphur valley of steaming vents left by the last eruption, crossed by the ropeway between Sounzan and Togendai. The black eggs are boiled in the hot springs and sold at the station.', bestTime: 'Midday — the ropeway shuts at 16:15 in winter', duration: '1 hour on the plateau', photoRating: 4, notes: 'The one hard December constraint on the Hakone loop: in December and January the ropeway runs 09:00-16:15 at all stations against 16:45 the rest of the year. That half hour decides whether a Shinjuku day trip closes the loop or has to double back, so leave Shinjuku 07:30-08:00. The ropeway also stops without notice for wind, maintenance and volcanic gas — check the operator\'s status page the morning of, not the night before, and keep the Togendai bus as the fallback. The fumarole floor itself has been closed to walkers since 2015.', location: 'Sengokuhara, Hakone-machi, Ashigarashimo-gun, Kanagawa 250-0631', priceHint: 'Ropeway ¥2,000 one way, ¥3,000 return; covered by the Hakone Freepass' },
  { id: 'ja61', image: '/images/japan/ja61.jpg', name: 'Kotoku-in (Great Buddha of Kamakura)', category: 'Day Trip', description: 'An 11.4m bronze Amida Buddha cast in 1252, sitting in the open air since the hall around it was destroyed by a tsunami in the fifteenth century. For ¥50 you can go inside the statue and see the casting seams.', bestTime: 'Morning, with Yokohama in the afternoon', duration: 'Half day', photoRating: 5, notes: 'Shinjuku to Kamakura is 61 minutes direct on the Shonan-Shinjuku Line, then five minutes on the Enoden to Hase and a seven-minute walk — about 1h20 door to door, the easiest full day trip from a Tokyo base. 08:00-17:00 Oct-Mar, entry until 16:45, inside the statue until 16:30, no closing days. Kamakura is a top-tier hatsumode town and is genuinely crushed Jan 1-3, with boarding queues at Kamakura Station running 40 minutes — take that on deliberately for the atmosphere or go Jan 5 onward.', location: '4-2-28 Hase, Kamakura, Kanagawa 248-0016', priceHint: '¥300 adult, plus ¥50 to go inside the statue' },
  { id: 'ja62', name: 'CUPNOODLES MUSEUM Yokohama', category: 'Day Trip', description: 'A design museum about instant noodles whose main draw is My CUPNOODLES Factory: you decorate a blank cup, choose a soup and four toppings, and it is sealed and shrink-wrapped in front of you.', bestTime: 'Afternoon, paired with Kamakura in the morning', duration: '1.5-2 hours', photoRating: 4, notes: 'A 45-minute activity the group will actually talk about afterwards, five minutes from Bashamichi and 55 minutes door to door from Shinjuku, ending at Chinatown for dinner. 10:00-18:00, last entry 17:00, closed Tuesdays and Dec 31 - Jan 1. The cup factory is same-day on a numbered ticket that can run out on a busy afternoon; the Chicken Ramen Factory needs advance booking. Verify before committing to a January date — the museum was closed for the whole of January 2026 for works and whether that repeats in 2027 was unknown as of September 2026.', location: '2-3-4 Shinko, Naka-ku, Yokohama, Kanagawa 231-0001', priceHint: '¥500 entry, plus ¥500 per cup at the noodle factory' },
  { id: 'ja63', image: '/images/japan/ja63.jpg', name: 'Nikko Toshogu', category: 'Day Trip', description: 'The mausoleum complex of Tokugawa Ieyasu, built in 1617 and carved and gilded to a density found nowhere else in Japan — the Yomeimon gate alone carries over 500 carvings. It stands in old cedar forest at 600m, so it is properly cold and often has snow.', bestTime: 'Whole day, on an early train', duration: 'Full day', photoRating: 5, notes: 'The honest note is that this is the thinnest fit of the Tokyo day trips, purely on travel time. The direct limited express from Shinjuku is about 2h but runs only once or twice a day, with the useful departure around 09:34; the alternative is Shinjuku to Asakusa, about 30 minutes, then 1h50 on an hourly service. Tobu limited express tickets go on sale at 09:00 one month before travel. 09:00-16:00 Nov-Mar. Toshogu itself stays open over New Year, but the Chuzenji embassy villas are shut December to March and the buses up the Irohazaka drop to one every 30-60 minutes in winter and can be rerouted in heavy snow.', location: '2301 Sannai, Nikko, Tochigi 321-1431', priceHint: 'About ¥1,600 adult' },
];

export const JAPAN_FOOD: Recommendation[] = [
  { id: 'jf1', image: '/images/japan/jf1.jpg', name: 'Ichiran Ramen', category: 'Ramen', description: 'Famous tonkotsu ramen chain with individual booth seating. Customize your noodle firmness, broth richness, and spice level.', bestTime: 'Anytime', duration: '30min', photoRating: 4, notes: 'Try extra firm noodles (barikata). Order extra noodles (kaedama). The Shibuya branch runs 24 hours and trades through New Year, which makes it one of the few certain meals between Dec 31 and Jan 3. Note the booths are individual by design — for three people the dividers have to be opened on request, and that is not guaranteed at peak.', location: 'B1F Iwamoto Building, 1-22-7 Jinnan, Shibuya-ku, Tokyo 150-0041', longDescription: 'Ichiran is a nationwide tonkotsu (pork-bone) ramen chain known for its solo-dining "flavour concentration booths" — individual partitioned seats where you order via a ticket machine and a paper form, choosing broth richness, garlic, spice and noodle firmness. Bowls arrive through a small hatch. It is a quick, reliably good and famously introvert-friendly ramen experience open long hours in Shibuya, Shinjuku and beyond.' },
  { id: 'jf2', image: '/images/japan/jf2.jpg', name: 'Fuunji Tsukemen', category: 'Ramen', description: 'Shinjuku\'s legendary dipping ramen (tsukemen). Rich, thick fish-based broth with perfectly chewy noodles.', bestTime: 'Lunch', duration: '45min', photoRating: 4, notes: '11:00-15:00 and 17:00-21:00, closed Sunday, plus a New Year break — Jan 5 onward is the realistic window on this trip. About ten counter seats and standing room, so three people get split up and there will be a queue. Finish with soup-wari.', location: '1F Hokuto Daiichi Building, 2-14-3 Yoyogi, Shibuya-ku, Tokyo 151-0053' },
  { id: 'jf3', image: '/images/japan/jf3.jpg', name: 'Conveyor Belt Sushi', category: 'Sushi', description: 'Fun, affordable sushi on rotating belt. Touch-screen ordering with plates delivered by mini train.', bestTime: 'Lunch', duration: '1 hour', photoRating: 3, notes: 'Uobei on Dogenzaka is the concrete one: ¥150 a plate, touchscreen ordering, three-lane express rail instead of a belt, and three adjacent counter seats is normal rather than lucky. 11:00-23:00 weekdays, 10:30-23:00 weekends and holidays, last order 22:30. Sushiro and Kura Sushi are the other chains.', location: '1F Dairoku Central Building, 2-29-11 Dogenzaka, Shibuya-ku, Tokyo 150-0043' },
  { id: 'jf4', image: '/images/japan/jf4.jpg', name: 'Convenience Store Food (Konbini)', category: 'Street Food', description: '7-Eleven, Lawson, FamilyMart serve surprisingly excellent onigiri, sandwiches, fried chicken, and desserts.', bestTime: 'Anytime', duration: '15min', photoRating: 2, notes: 'Lawson\'s karaage is legendary. Try egg sandwiches and melon pan.', location: 'Everywhere' },
  { id: 'jf5', image: '/images/japan/jf5.jpg', name: 'Gyukatsu Motomura', category: 'Restaurant', description: 'Premium deep-fried wagyu beef cutlet cooked to your preference on a hot stone at your table.', bestTime: 'Lunch', duration: '1 hour', photoRating: 4, notes: 'Queue early — no reservations for counter seats. Medium rare on the hot stone is perfection. The Kabukicho branch is five minutes from the base and runs 11:00-22:00, last order 21:00; Jan 1-3 hours are not published, so confirm before building a dinner around it.', location: 'B2F WaMall, 1-25-3 Kabukicho, Shinjuku-ku, Tokyo 160-0021' },
  { id: 'jf6', image: '/images/japan/jf6.jpg', name: 'Matcha Desserts at Tsujiri', category: 'Dessert', description: 'Premium matcha from Uji, Kyoto in parfaits, ice cream, and traditional tea. Rich, bitter-sweet green tea perfection.', bestTime: 'Late, in the last hour before closing — the queue moves fastest then', duration: '45min', photoRating: 4, notes: 'The Gion flagship sits directly on the evening Gion walk, three minutes from Gion-Shijo. Shop at street level on Shijo-dori, tearoom on the floors above. 10:00-21:00, tearoom last order 20:00 weekdays and 19:30 weekends, no fixed closing day but shortened hours over New Year. No reservations; walk in and queue.', location: '573-3 Gionmachi Minamigawa, Higashiyama Ward, Kyoto 605-0074', priceHint: 'Parfait ¥1,300-1,800' },

  // — Tokyo. The two that trade around the clock are here because Jan 1-3 is the problem:
  // most independents shut and the chains and the 24-hour counters are what is left.
  { id: 'jf7', name: 'Sushi Zanmai Honten', category: 'Sushi', description: 'The original branch of the chain whose owner makes the headlines bidding on the year\'s first tuna, on the corner of the Tsukiji outer market. Counter and table seating, an illustrated menu, and it never shuts.', bestTime: 'Any hour at all', duration: '1 hour', photoRating: 3, notes: '24 hours, every day of the year, which is the whole reason it earns a slot — it works after a night out or before a 05:00 market run, which almost nothing else nearby does. One of the few reliable Jan 1 meals in this part of Tokyo, though supply is thinner while the wholesale markets are shut. No reservations; expect a queue at peak lunch.', location: '4-11-9 Tsukiji, Chuo-ku, Tokyo 104-0045', priceHint: 'Nigiri from around ¥200 a piece; a set around ¥2,000-4,000' },
  { id: 'jf8', name: 'Sugoi Niboshi Ramen Nagi, Golden Gai', category: 'Ramen', description: 'Dried-sardine ramen served up a near-vertical staircase in a wooden Golden Gai house. The broth is heavy on niboshi and the room seats about ten.', bestTime: 'Whenever the night ends', duration: '30min', photoRating: 3, notes: 'The 24-hour ramen that is inside Golden Gai itself, so a Shinjuku night ends where it already is. Ticket machine, cash safest. It advertises year-round 24-hour operation, but it is a small owner-run shop and can still take a short year-end break — look at the door rather than promising it.', location: '2F, Golden Gai G2 Street, 1-1-10 Kabukicho, Shinjuku-ku, Tokyo 160-0021', priceHint: '¥1,000-1,500 a bowl' },
  { id: 'jf9', name: 'Ponta Honke', category: 'Restaurant', description: 'A tonkatsu house open since 1905 and generally credited with inventing the dish. The signature katsuretsu is a lean pork loin fried pale in lard and served without the usual heavy sauce, at a wooden counter.', bestTime: 'The first lunch sitting', duration: '1 hour', photoRating: 4, notes: 'Ten minutes on foot from Ameyoko rather than a detour across the city. Tue-Sat 11:00-14:00 (last order 13:45) and 16:30-20:20 (last order 19:45), closed Mondays — which takes out Dec 28 and Jan 4. No reservations for small groups, so queue for the first sitting. A restaurant of this vintage also shuts for several days around New Year; assume Dec 31 - Jan 4 is unavailable unless confirmed.', location: '3-23-3 Ueno, Taito-ku, Tokyo 110-0005', priceHint: 'Katsuretsu around ¥3,000-4,000; cheaper at lunch' },
  { id: 'jf10', name: 'Motsuyaki Daitoryo', category: 'Street Food', description: 'An open-fronted offal grill on the Ameyoko side of Ueno where the drinking spills onto plastic crates on the pavement. Grilled skewers and a pot of nikomi stew, with shochu highballs, from mid-morning onward.', bestTime: 'Afternoon, straight off the Ameyoko walk', duration: '1 hour', photoRating: 4, notes: 'The standing bar that opens at 10:00, costs almost nothing and is the loudest daytime drinking in east Tokyo. Roughly 10:00-24:00 daily; a branch a few doors along runs to 23:30 if the main shop is full. Hours are secondary-source only, so confirm at the door. Independent Ueno bars usually shut for at least Jan 1 and some to Jan 3.', location: '6-10-14 Ueno, Taito-ku, Tokyo 110-0005', priceHint: 'Skewers ¥150-250 each; a drink around ¥400' },
  { id: 'jf11', image: '/images/japan/jf11.jpg', name: 'Monja Kondo Honten', category: 'Restaurant', description: "One of the long-running shops on Tsukishima's Monja Street, a few hundred metres of nothing but monjayaki. You cook the batter yourself on the griddle set into the table; staff start the first one off, then it is on you.", bestTime: 'Evening', duration: '1.5-2 hours', photoRating: 4, notes: 'A table-griddle meal three people cook together beats another sit-down dinner. Two or three monja between three people. Roughly 17:00-22:00 on weekdays with weekend lunch service, and hours vary shop by shop along the street. Shops take names at the door rather than reservations. Monja Street closes for several days over New Year, generally Dec 31 - Jan 3, so aim for Dec 28-30 or Jan 5 onward.', location: '3-12-10 Tsukishima, Chuo-ku, Tokyo 104-0052', priceHint: '¥1,200-2,000 per monja' },
  { id: 'jf12', name: 'Suzukien Asakusa Honten', category: 'Dessert', description: 'A tea merchant behind Senso-ji selling matcha gelato in seven graded strengths, from mild up to a No. 7 it bills as the richest in the world. It is a counter with a couple of stools, not a cafe.', bestTime: 'Daytime only', duration: '20min', photoRating: 4, notes: 'The seven-shade line-up is the most photographed ice cream in Tokyo. 10:00-17:00, closed the third Wednesday of the month — so it shuts well before dark and has to come before an afternoon Skytree slot, not after. Small Asakusa shops commonly close Jan 1-3; check on the day.', location: '3-4-3 Asakusa, Taito-ku, Tokyo 111-0032', priceHint: 'Around ¥600 a single scoop; No. 7 costs more' },
  { id: 'jf13', image: '/images/japan/jf13.jpg', name: 'Yokohama Chinatown', category: 'Street Food', description: 'The largest Chinatown in Japan — roughly 300 restaurants and food stalls in a ten-block grid behind painted gates, selling steamed buns, xiaolongbao and grilled skewers to eat standing up.', bestTime: '17:00, when it is already dark and the lanterns are lit', duration: '2 hours', photoRating: 4, notes: 'Motomachi-Chukagai is one stop from Minatomirai, so it slots onto the end of a Yokohama half-day. Most street stalls run roughly 10:00-20:00 and the restaurants later. This is one of the few food districts near Tokyo that stays busy through Jan 1-3, and it is 55 minutes from Shinjuku — a real answer if the New Year dinner problem bites.', location: 'Yamashitacho, Naka-ku, Yokohama, Kanagawa 231-0023', priceHint: '¥500-1,500 for a stall crawl' },
  { id: 'jf14', name: 'Starbucks Reserve Roastery Tokyo', category: 'Café', description: 'A four-floor roastery on the Meguro River with a copper cask running the height of the building and a bakery counter on the ground floor.', bestTime: 'Breakfast', duration: '1 hour', photoRating: 4, notes: 'Doors open at 07:00, earlier than almost anything else worth eating at in Nakameguro, and it beats a konbini onigiri. 07:00-22:00, some listings give 23:00. Chain-operated, so it generally trades through New Year when the independent cafes around it do not, though hours can shorten on Jan 1.', location: '2-19-23 Aobadai, Meguro-ku, Tokyo 153-0042', priceHint: '¥700-2,000' },

  // — Kyoto and Kansai. Two of these are the answer to a specific dated problem: Dec 24 is the
  // biggest restaurant night of the Japanese year, and Dec 27 needs breakfast before an 11:00 checkout.
  { id: 'jf15', name: 'Menami', category: 'Restaurant', description: "An obanzai house trading for over eighty years on Kiyamachi, where the day's dishes sit in bowls along the counter and you order by pointing at them. Kyoto home food built on seasonal vegetables, yuba and fish, meant to be eaten alongside sake.", bestTime: 'From 15:00, eight minutes on foot from Shijo-Kawaramachi', duration: '2 hours', photoRating: 4, notes: 'The Christmas Eve answer. 15:00-22:00, last order 21:30, closed Wednesdays, so Dec 24-26 are all open. Booking is by phone only, taken in the afternoon and in Japanese — that changes who in the group has to make the call, so settle it early. Dec 24 is the single biggest restaurant night of the Japanese year and a walk-in trio will be turned away; book by early December.', location: '96 Nakajimacho, Kiyamachi-dori Sanjo-agaru, Nakagyo Ward, Kyoto 604-8004', priceHint: '¥3,000-5,000 a head with drinks' },
  { id: 'jf16', name: 'Giro Giro Hitoshina', category: 'Restaurant', description: 'A converted warehouse on the Takase canal serving a set kaiseki course at a fraction of the usual Kyoto price, plated in front of you at an open counter. The menu changes constantly and the room is loud rather than hushed.', bestTime: 'Dinner', duration: '2-2.5 hours', photoRating: 4, notes: 'A real multi-course Kyoto meal for around ¥5,000 instead of ¥15,000, in a room where three people in their twenties will not feel out of place. Staff work in English. 17:30-23:00, closed the last Monday of each month — Dec 28 in 2026, which is after the Kyoto leg ends. Reservations are effectively required, one to four weeks ahead for a weekend.', location: '420-7 Nambacho, Nishikiyamachi-dori Matsubara-sagaru, Shimogyo Ward, Kyoto 600-8025', priceHint: 'Course ¥4,500-5,500; ¥5,000-6,000 a head with drinks' },
  { id: 'jf17', name: 'Honke Daiichi Asahi', category: 'Ramen', description: 'A ramen shop trading since 1947 five minutes east of Kyoto Station, serving the local soy-and-pork-bone style under a sheet of sliced chashu and a pile of green onion.', bestTime: '06:00, before a checkout or a train', duration: '30min', photoRating: 3, notes: 'The only genuinely early food on the Kyoto leg, and the obvious breakfast on the day the group moves to Tokyo. 06:00-01:00, closed Thursdays — which rules out Dec 24 2026. A queue forms before the shutter goes up. Shinpuku Saikan, the black-broth rival, is directly next door. It takes a short New Year break most years.', location: '845 Higashishiokoji Mukaiharacho, Shimogyo Ward, Kyoto 600-8213', priceHint: '¥900-1,300 a bowl' },
  { id: 'jf18', name: 'Yudofu Sagano', category: 'Restaurant', description: 'A tofu specialist beside Tenryu-ji serving the yudofu set as a simmering pot of silken tofu with sesame tofu, konnyaku sashimi and tempura around it, eaten looking onto a garden.', bestTime: 'Lunch, after the bamboo grove', duration: '1.5 hours', photoRating: 4, notes: 'The closest named yudofu house to the bamboo grove exit, and its 16:30 last order fits an Arashiyama morning that ends at the monkey park. 11:00-17:30. Tatami seating, so three is comfortable. Walk-ins for the standard set; the multi-course version needs two days\' notice. It keeps irregular holidays, meaning it can be shut on the day with no notice, and it closes for several days around New Year.', location: '45 Sagatenryuji Susukinobabacho, Ukyo Ward, Kyoto 616-8385', priceHint: 'Yudofu set about ¥3,800; budget ¥4,000-6,000 a head' },
  { id: 'jf19', name: 'Inoda Coffee Honten', category: 'Café', description: 'A kissaten opened in 1940 around a courtyard garden, serving its own dark roast with the milk and sugar already stirred in unless you ask otherwise.', bestTime: 'On the way back from a dawn shoot, not on the way out', duration: '1 hour', photoRating: 4, notes: 'It opens at 07:00, which makes it the earliest proper cafe in central Kyoto — but a 06:30 arrival at Fushimi Inari means leaving before it opens, so it is the reward at the end of that morning rather than the fuel for it. 07:00-18:00, last order 17:30, open every day of the year including New Year. No reservations.', location: '140 Doyucho, Sakaimachi-dori Sanjo-sagaru, Nakagyo Ward, Kyoto 604-8118', priceHint: 'Coffee about ¥700; breakfast set about ¥1,500' },
  { id: 'jf20', name: 'Nakatanidou', category: 'Street Food', description: 'A mochi shop in Nara that pounds yomogi mochi in the street outside — two people swinging a mallet at high speed while a crowd films it. The kusa-mochi is sold warm, one piece at a time, from the counter.', bestTime: 'On the walk in from Kintetsu-Nara', duration: '15min', photoRating: 5, notes: 'Street food plus spectacle, 400m from Kintetsu-Nara Station, so it costs ten minutes on the walk to Todai-ji rather than a detour. Roughly 09:00-18:30 daily. The pounding demonstrations run several times a day and are not on a published timetable — treat it as luck on the way past, not as a scheduled item.', location: '29 Hashimotocho, Nara, Nara 630-8217', priceHint: 'About ¥150-200 per mochi' },
  { id: 'jf21', name: 'Nakamura Tokichi Byodoin-ten', category: 'Dessert', description: 'The Byodo-in branch of an 1854 Uji tea merchant, serving matcha jelly, soba and thick koicha in a room over the tea shop. Uji is where Japanese green tea was first cultivated commercially.', bestTime: 'Outside the lunch rush', duration: '1 hour', photoRating: 4, notes: 'A reason to stay in Uji past the temple, and a matcha stop that is not the Tsujiri card. It is on the Omotesando approach, two minutes from the Byodo-in gate — note the older honten by JR Uji Station is a different shop half a kilometre away. Roughly 10:00-17:00, last order about 16:30. Walk-in with a numbered-ticket queue at peak times.', location: '5-1 Ujirenge, Uji, Kyoto 611-0021', priceHint: '¥1,000-2,000 per person' },
];

